// The per-pane DETECTOR: one machine, plus everything that turns its verdicts into a control
// stream — the type-26 basename edge, the type-27 dedupe anchor, the type-36 intent latch and the
// type-21 title retirement. §4b's handle convention: no two calls on one handle may overlap.
//
// Every fold answers a SLOT MASK naming what it owes — 1 foreground, 2 status, 4 intent, 8 title
// retirement — and the named slots are then read back off the handle. The emission lives there
// until the next fold replaces it, so a caller reads it before folding again. A fold on a null
// handle answers 0, which is indistinguishable from a fold that owed nothing, and is correct.
#define SLOPDESK_AGENT_EMIT_FOREGROUND 1u
#define SLOPDESK_AGENT_EMIT_STATUS     2u
#define SLOPDESK_AGENT_EMIT_INTENT     4u
#define SLOPDESK_AGENT_EMIT_TITLE      8u

// detector_constant index: 0 default done->idle, 1 the report grace window, 2 the wrapper
// suppression window, 3 the intent clamp in scalars.
double slopdesk_agent_detector_constant(uint8_t index);

SlopDeskAgentDetector *slopdesk_agent_detector_new(double done_to_idle_timeout);
void slopdesk_agent_detector_free(SlopDeskAgentDetector *handle);

uint32_t slopdesk_agent_detector_sample(SlopDeskAgentDetector *handle,
                                        const uint8_t *name, size_t len, double now);
// The raw hook POST body. Validate-then-drop: a body this build cannot read answers 0.
uint32_t slopdesk_agent_detector_hook(SlopDeskAgentDetector *handle,
                                      const uint8_t *body, size_t len, double now);
// A null `message` is NO message, which is not the same as an empty one.
uint32_t slopdesk_agent_detector_report(SlopDeskAgentDetector *handle,
                                        const uint8_t *state, size_t state_len,
                                        const uint8_t *message, size_t message_len, double now);
uint32_t slopdesk_agent_detector_tick(SlopDeskAgentDetector *handle, double now);
// The COMPACT detection: the rule id and fallback reason a full verdict carries are for
// explanation, and nothing downstream of here reads either.
uint32_t slopdesk_agent_detector_screen(SlopDeskAgentDetector *handle,
                                        const SlopDeskAgentDetection *detection, double now);
uint32_t slopdesk_agent_detector_title(SlopDeskAgentDetector *handle,
                                       const uint8_t *title, size_t len, double now);
uint32_t slopdesk_agent_detector_user_input(SlopDeskAgentDetector *handle,
                                            const uint8_t *bytes, size_t len, double now);
uint32_t slopdesk_agent_detector_reestablish(SlopDeskAgentDetector *handle);

// The last fold's emission. -1 = that slot was not filled; 0 = filled with the empty string, which
// is a real answer everywhere here (a cleared intent, a label the agent left blank).
ptrdiff_t slopdesk_agent_detector_emit_foreground(SlopDeskAgentDetector *handle,
                                                  uint8_t *out, size_t cap);
ptrdiff_t slopdesk_agent_detector_emit_status_label(SlopDeskAgentDetector *handle,
                                                    uint8_t *out, size_t cap);
ptrdiff_t slopdesk_agent_detector_emit_intent(SlopDeskAgentDetector *handle,
                                              uint8_t *out, size_t cap);
// (state << 8) | kind — one door, because the two bytes are one frame.
uint16_t slopdesk_agent_detector_emit_status_bytes(SlopDeskAgentDetector *handle);

// The detector's CURRENT state, which is not the last emission.
uint8_t slopdesk_agent_detector_status(SlopDeskAgentDetector *handle);
bool    slopdesk_agent_detector_is_quiet(SlopDeskAgentDetector *handle);
bool    slopdesk_agent_detector_has_authoritative_feed(SlopDeskAgentDetector *handle);
bool    slopdesk_agent_detector_suppresses_child_notifications(SlopDeskAgentDetector *handle);
ptrdiff_t slopdesk_agent_detector_status_label(SlopDeskAgentDetector *handle,
                                               uint8_t *out, size_t cap);
ptrdiff_t slopdesk_agent_detector_session_intent(SlopDeskAgentDetector *handle,
                                                 uint8_t *out, size_t cap);
// The type-27 anchor — the value BEHIND the edge, for a client that missed it.
bool      slopdesk_agent_detector_has_last_status(SlopDeskAgentDetector *handle);
uint8_t   slopdesk_agent_detector_last_status_state(SlopDeskAgentDetector *handle);
uint8_t   slopdesk_agent_detector_last_status_kind(SlopDeskAgentDetector *handle);
ptrdiff_t slopdesk_agent_detector_last_status_label(SlopDeskAgentDetector *handle,
                                                    uint8_t *out, size_t cap);

// The detector's pure statics, callable without one. -1 = no answer.
ptrdiff_t slopdesk_agent_intent_line(const uint8_t *prompt, size_t len, uint8_t *out, size_t cap);
ptrdiff_t slopdesk_agent_topic_line(const uint8_t *title, size_t len, uint8_t *out, size_t cap);
uint8_t   slopdesk_agent_block_kind(uint8_t standing, uint8_t ledger, uint8_t event, bool blocked);

// A screen-dissent window in seconds: 0 how long the screen must claim BLOCKED before it may raise
// a block the hook feed never announced, 1 how long it must contradict the other way before it may
// release one. The two are asymmetric on purpose, and the asymmetry IS the policy. Unknown index
// answers 0, which is no window rather than a plausible one.
double slopdesk_agent_dissent_seconds(uint8_t index);

// The foreground JOB has no doors here. It used to have six plus a resolver callback, so Swift
// could hand over a process group it had probed itself; both halves live in Rust now and the
// question is asked once, as slopdesk_pty_foreground_agent below (macOS only, like the probe).

// Whether the host should be holding a system-sleep assertion right now — the WHOLE state, asked on
// every fold, so the daemon's create⇄release stays balanced against the answer rather than an edge.
bool    slopdesk_agent_should_prevent_sleep(bool any_agent_working, bool enabled);

// MARK: - The workspace document's solvers (`rust/slopdesk-workspace`)
//
// The document's VALUE TYPES stay in Swift — 262 files import them, and a `SplitNode` is what
// SwiftUI diffs. What crosses is the half that decides: where focus lands, what order the sidebar's
// sections come in, which tab survives a close. Everything is flat: an array of `(id, rect)` in, an
// answer out, and no state owned between calls.

// A UUID in its own byte order, so a sort by id agrees on both sides.
typedef struct { uint8_t bytes[16]; } SlopDeskWsUuid;

// Laid out exactly as Swift's `CGRect` reads it.
typedef struct { double x, y, width, height; } SlopDeskWsRect;
typedef struct { double x, y; } SlopDeskWsPoint;

typedef struct {
    SlopDeskWsUuid id;
    SlopDeskWsRect rect;
} SlopDeskWsFrame;

// A slice of the caller's strings blob. `present == false` is Swift's `nil`; a present span of
// length 0 is an empty string, which is not the same question.
typedef struct {
    size_t offset;
    size_t len;
    bool   present;
} SlopDeskWsSpan;

typedef struct {
    SlopDeskWsUuid id;
    SlopDeskWsSpan key;
} SlopDeskWsKeyedTab;

// `<Token>`-marked text as the bytes a PTY receives.
size_t slopdesk_ws_send_keys(const uint8_t *bytes, size_t len, uint8_t *out, size_t cap);
bool slopdesk_ws_key_token(const uint8_t *name, size_t len, uint8_t *out, size_t cap,
                           size_t *needed);
size_t slopdesk_ws_shell_quote(const uint8_t *bytes, size_t len, bool bare_if_safe, uint8_t *out,
                               size_t cap);
size_t slopdesk_ws_redact_secrets(const uint8_t *bytes, size_t len, uint8_t *out, size_t cap);

// The placeholder a masked credential collapses to. §4-shaped. Asked for because it is what a
// caller ASSERTS against, and a transcribed copy passes on a mask the redactor stopped producing.
size_t slopdesk_ws_secret_mask(uint8_t *out, size_t cap);
bool   slopdesk_ws_looks_secret(const uint8_t *bytes, size_t len);
// The pane-directory classifier and the leaf a row shows. `slopdesk_ws_cwd_display_name` answers 0
// for "no name to show" — an absent, blank or all-slashes path — which a real name can never be.
bool   slopdesk_ws_transient_plugin_cwd(const uint8_t *bytes, size_t len);
size_t slopdesk_ws_cwd_display_name(const uint8_t *bytes, size_t len, uint8_t *out, size_t cap);
// The WHOLE directory, as a badge prints it: a `/Users/<name>` or `/home/<name>` prefix collapsed to
// `~`, and a trailing `/` marking it a directory. Matched by SHAPE, never against this machine's own
// home — the path came off the remote host. `0` here means the path was empty.
size_t slopdesk_ws_cwd_badge_path(const uint8_t *bytes, size_t len, uint8_t *out, size_t cap);
uint8_t slopdesk_ws_paste_risk(const uint8_t *bytes, size_t len, bool target_is_secure,
                               size_t max_length);

// ---- A clipboard as the KEYS that type it --------------------------------------
//
// macOS drops synthetic UNICODE events at a secure field, and takes synthetic KEY events, so the
// only paste a `sudo` prompt accepts is the text spelled back out as US-QWERTY presses. The unit
// walked is the grapheme CLUSTER, never the scalar: a decomposed "é" walked as scalars would type
// a bare "e" into a password field and report one skip, which is a DIFFERENT password accepted
// with nothing on screen to say so.

// The largest clipboard, in CLUSTERS, that will be replayed. Also the ceiling
// `slopdesk_ws_paste_risk` refuses past — one number, asked for at both sites.
#define SLOPDESK_KEYSTROKE_MAX_LENGTH 4096

// `[u32 BE skipped][u32 BE count]` then `count` × `[u16 BE key_code][u8 shift]`. Never 0: an empty
// clipboard is the eight header bytes with both counts zero, which is not §4's refusal. `skipped`
// counts a cluster with no key AND every cluster past the cap — in both cases the field will not
// hold what the clipboard did, and the caller has one banner to say so with.
size_t slopdesk_keystroke_replay(const uint8_t *text, size_t text_len, uint8_t *out, size_t cap);

// ---- The same keys, asked for by POSITION ---------------------------------------
//
// A hardware keyboard driving a remote DESKTOP sends the layout-level KEYCODE, so the HOST's layout
// and input method interpret it server-side — a key sent as a pre-baked character is invisible to a
// keycode-driven IME composer, and Vietnamese Telex would never compose. The USB HID usage is the
// one thing a key event carries that names POSITION rather than meaning.
//
// Its printable run is the table above, read by index instead of by character: the same 47
// `kVK_ANSI_*` numbers, resolved through the character the key types, so they exist once. What the
// module adds is the run that has no character — escape, backspace, F1…F12, the navigation cluster,
// the keypad, the two ISO extras and both sides of every modifier.
//
// The answer is a value plus a FLAG and not a keycode alone, because `kVK_ANSI_A` is `0` and `a` is
// the commonest key on the board: a sentinel here would make "the letter a" and "this key has no
// macOS equivalent" the same answer, and the second one must send NOTHING.
typedef struct {
  uint16_t key_code;
  bool     mapped;
} SlopDeskHidVirtualKey;

SlopDeskHidVirtualKey slopdesk_hid_virtual_key(uint16_t hid_usage);
// Either side of ⌘⇧⌃⌥, or Caps Lock. The caller latches these so a focus change that swallows the
// release can synthesize the missing key-up.
bool                  slopdesk_hid_is_modifier(uint16_t hid_usage);

// ---- A device panel's hardware key -------------------------------------------
//
// The Android panel and the simulator panel ask one question in one order — does this key have a
// character of its own? — and differ only at the last step, where one wants a `KeyEvent` keycode
// and the other a `KeyboardEvent.code` string. `hid` picks the NUMBERING: a Mac reports a virtual
// keycode, an iPad a USB HID usage. That is one bit, so it rides as one rather than doubling every
// door, the way `slopdesk_settings_row_shown(index, mac)` carries which half is asking.
//
// The HID side is DERIVED from `slopdesk_hid_virtual_key` above, not tabulated. Four Swift maps
// became two here, because two of them were that composition written out — and a written-out join
// drifts from the thing it joins.

// The simulator server's `KeyboardEvent.code`, or `0` for a key that types text and belongs on the
// `type` envelope instead. `0` is safe as "no code" where it was not for the keycode door above:
// every name this vocabulary answers is non-empty, so an empty delivery is outside the answer's
// range rather than colliding with a real one.
size_t slopdesk_panel_simulator_key_code(uint16_t code, bool hid, uint8_t *out, size_t cap);

// What the Android panel should do about one key-down, TAGGED by its first byte.
#define SLOPDESK_ANDROID_KEY_NOTHING 0
#define SLOPDESK_ANDROID_KEY_KEYCODE 1
#define SLOPDESK_ANDROID_KEY_TEXT    2
// `NOTHING` is the whole answer. `KEYCODE` is followed by the `KeyEvent` keycode and the meta state
// as four big-endian bytes each. `TEXT` is followed by the UTF-8 to type. A return larger than
// `cap` means nothing was written — ask again at that size.
//
// One blob rather than a "which case" door plus a conditional second call: the caller cannot know
// the shape until the rule has run, and two crossings for one question is a window in which they
// could disagree.
//
// `characters` is what the near side's layout produced; `bare` is the same press with the layout's
// modifier handling stripped. Each carries a PRESENT flag beside its pair, because absent and empty
// are different answers here — absent falls back to `bare`, empty means the press produced nothing
// — and a null pointer standing for both would silently turn the second into the first.
size_t slopdesk_panel_android_key_resolve(uint16_t code, bool hid, const uint8_t *characters,
                                          size_t characters_len, bool characters_present,
                                          const uint8_t *bare, size_t bare_len, bool bare_present,
                                          uint8_t modifiers, uint8_t *out, size_t cap);

// Android's `META_*` bitmask for a set of held modifiers. SHIFT is deliberately not in it: the near
// side has already applied it — the characters arriving with the event are already upper case — so
// folding it in would ask the device to apply it twice. Exported beside the door above because the
// panel's toolbar presses a keycode with no key event behind it.
uint32_t slopdesk_panel_android_meta_state(uint8_t modifiers);

// ---- Peek & Reply: what the card sends, and the tail it shows -------------------
//
// Which PANE it answers is `slopdesk_agent_peek_*` above. Every reply carries its own single
// trailing newline; `0` means send NOTHING, which is an empty, whitespace-only or bare-`!` field.
size_t slopdesk_ws_peek_reply_text(const uint8_t *field, size_t field_len, uint8_t *out, size_t cap);
// A quick-answer digit typed into an empty field. `0` for anything outside 1–9.
size_t slopdesk_ws_peek_quick_answer(int32_t digit, uint8_t *out, size_t cap);
// The `limit` newest blocks as one line each, oldest-first, from two PARALLEL flat blobs under one
// count. `[u32 BE lines]`, then that many `[u32 BE length]` words, then the bytes back to back —
// the count leads so "this pane has no blocks yet" is not §4's "ask again".
size_t slopdesk_ws_peek_recent_lines(const uint8_t *commands, size_t commands_len,
                                     const size_t *command_lengths, const uint8_t *statuses,
                                     size_t statuses_len, const size_t *status_lengths,
                                     size_t count, size_t limit, uint8_t *out, size_t cap);

// What a preset or a template types into the pane it just opened: a literal `cd` line when a
// directory is set, then the command through the token parser. A null or empty `cwd` is "no
// directory". The `cd` line never reaches the parser — a `<Enter>` inside a path would otherwise
// end the quoted line early and run the rest as its own command.
size_t slopdesk_ws_launch_keystrokes(const uint8_t *command, size_t command_len,
                                     const uint8_t *cwd, size_t cwd_len,
                                     uint8_t *out, size_t cap);

// What the host may listen on, and what to tell the operator when it cannot. `0` is a valid port
// and means "OS-assigned"; the two errno questions are here because a bind conflict can arrive as
// a FAILURE or hide inside the framework's retryable waiting state, and both spell it in text.
bool    slopdesk_ws_listen_port_is_valid(int64_t raw);
// `raw` as a bindable port, or `-1` for one out of range. Signed rather than §4-shaped because 0 is
// a REAL answer here — it is the OS-assigned port — and a port is unsigned, so -1 is outside the
// answer's range by construction the way slopdesk_fuzzy_rank's refusal is. The refusal is never a
// coercion: clamping mapped -5 to 0, an OS-assigned port nobody asked for and then persisted, and
// 99999 to 65535 while the field on screen still read 99999. The predicate above is what the text
// field asks per keystroke to decide whether Start is dark, where there is no port to carry back;
// this is what the bind asks once, where there is. Composing the two on the near side was the pair
// this door closes — the refusal was decided in Rust and the cast in Swift, agreeing only because
// `u16`'s range happens to be the accepted range.
int32_t slopdesk_ws_listen_port(int64_t raw);
bool    slopdesk_ws_listen_detail_is_address_in_use(const uint8_t *bytes, size_t len);
bool    slopdesk_ws_listen_waiting_errno_is_fatal(int32_t posix_errno);

// Direction: 0 left · 1 right · 2 up · 3 down · 4 next · 5 previous.
bool slopdesk_ws_focus_neighbor(const SlopDeskWsFrame *frames, size_t count,
                                SlopDeskWsUuid pane, uint8_t direction, SlopDeskWsUuid *answer);
bool slopdesk_ws_focus_cycle(const SlopDeskWsUuid *panes, size_t count,
                             SlopDeskWsUuid from, bool forward, SlopDeskWsUuid *answer);

// 0 bytes = absent. A present key is never empty, so the two never collide.
size_t slopdesk_ws_project_key(const uint8_t *bytes, size_t len, bool present,
                               uint8_t *out, size_t cap);
size_t slopdesk_ws_section_header(const uint8_t *bytes, size_t len, bool present,
                                  uint8_t *out, size_t cap);
bool   slopdesk_ws_section_precedes(const uint8_t *left, size_t left_len, bool left_present,
                                    const uint8_t *right, size_t right_len, bool right_present);

// `tabs` is the display order and still CONTAINS `closing`; each entry carries the project key the
// caller's closure answered, spanning into `strings`.
bool slopdesk_ws_successor_after_close(SlopDeskWsUuid closing,
                                       const SlopDeskWsKeyedTab *tabs, size_t tab_count,
                                       const uint8_t *strings, size_t strings_len,
                                       const SlopDeskWsUuid *history, size_t history_count,
                                       SlopDeskWsUuid *answer);

// Where a newly opened tab lands in the tab bar, under the `new-tab-position` policy `position`
// names: `auto`, `end` or `after-current`. Those spellings are the client's persisted setting and
// the settings catalog's own option tokens for this group, so both sides were already holding them
// — which is why the policy crosses as its spelling rather than as the intent wire's byte, a byte
// here being a third map from the same three cases to the same three numbers. A spelling this build
// has never had places the tab where the DEFAULT does rather than refusing, and that fallback is the
// crate's, so it is one answer and not one per reader.
//
// Both counts are signed because the caller's are: a tab list is counted in `Int`, and an active
// index read out of a restored document can name a tab that has since closed. A negative count is
// no tabs, a negative active index is the first one, and the answer is always a valid insertion
// index in 0..=max(tab_count, 0). There is no refusal in it — every policy places every list — and 0
// is a real answer, being where a tab lands in an empty bar, which is why this is not §4-shaped.
int64_t slopdesk_ws_new_tab_index(const uint8_t *position, size_t position_len,
                                  int64_t active_index, int64_t tab_count);

// What a pane is CALLED, in the one precedence every surface that names one shares — the rail row,
// the tab strip, the pane switcher, the window title. Each `0` below is documented per door: for
// the name and mark doors it is "no answer, keep your own rung"; for the two TITLE doors it
// is the EMPTY title, which the at-root idle shell yields on purpose so the live chain can speak.
size_t slopdesk_ws_slot_process_name(const uint8_t *bytes, size_t len, bool present,
                                     uint8_t *out, size_t cap);
size_t slopdesk_ws_process_display_name(const uint8_t *bytes, size_t len, bool present,
                                        uint8_t *out, size_t cap);
bool   slopdesk_ws_slot_label_is_command(const uint8_t *bytes, size_t len, bool present);
bool   slopdesk_ws_is_agent_session(bool has_agent_status, const uint8_t *bytes, size_t len,
                                    bool present);
// Asked for rather than transcribed: a copy pinned to a different presentation would draw a
// different glyph beside the same rows.
size_t slopdesk_ws_agent_title_mark(uint8_t *out, size_t cap);
uint32_t slopdesk_ws_command_title_min_duration_ms(void);
size_t slopdesk_ws_agent_marked_title(const uint8_t *bytes, size_t len, uint8_t *out, size_t cap);
size_t slopdesk_ws_normalized_program_title(const uint8_t *bytes, size_t len, bool present,
                                            uint8_t *out, size_t cap);

// The two composite inputs. Every string is a span into the ONE `strings` blob passed alongside —
// one pointer, one lifetime, one scope, where a `(ptr, len)` per field would mean seven nested
// borrows per row per frame. `kind` is a PaneKind byte: 0 terminal, 1 desktop.
typedef struct {
    uint8_t        kind;
    SlopDeskWsSpan spec_title;
    bool           user_renamed;
    SlopDeskWsSpan cwd;
    SlopDeskWsSpan live_title;
    SlopDeskWsSpan process_label;
    SlopDeskWsSpan project_key;
} SlopDeskWsRowTitle;

// Line two. `spec_title` absent is a pane with no spec, which has no second line at all;
// `project_key` absent is a surface with no section headers, where the full path is the only place
// the location can be shown.
typedef struct {
    uint8_t        kind;
    SlopDeskWsSpan spec_title;
    bool           video_present;
    SlopDeskWsSpan video_app_name;
    SlopDeskWsSpan video_title;
    SlopDeskWsSpan cwd;
    SlopDeskWsSpan live_title;
    SlopDeskWsSpan project_key;
} SlopDeskWsSubtitle;

typedef struct {
    SlopDeskWsSpan structural_title;
    bool           user_renamed;
    bool           is_agent;
    SlopDeskWsSpan intent;
    SlopDeskWsSpan running_command;
    SlopDeskWsSpan program_title;
    SlopDeskWsSpan process_title;
    uint8_t        kind;
    SlopDeskWsSpan cwd_title;
    SlopDeskWsSpan fallback;
} SlopDeskWsLiveRowTitle;

// `has_duration == false` is a block still RUNNING, which is a different fact from one that
// finished instantly — the title rule skips both, but for different reasons.
typedef struct {
    SlopDeskWsSpan text;
    bool           has_duration;
    uint32_t       duration_ms;
} SlopDeskWsCommandTitleBlock;

size_t slopdesk_ws_row_title(SlopDeskWsRowTitle inputs, const uint8_t *strings,
                             size_t strings_len, uint8_t *out, size_t cap);
// `0` = no second line, which is a single-line row.
size_t slopdesk_ws_pane_subtitle(SlopDeskWsSubtitle inputs, const uint8_t *strings,
                                 size_t strings_len, uint8_t *out, size_t cap);
size_t slopdesk_ws_last_command_title(const SlopDeskWsCommandTitleBlock *blocks, size_t count,
                                      const uint8_t *strings, size_t strings_len,
                                      uint8_t *out, size_t cap);
size_t slopdesk_ws_live_row_title(SlopDeskWsLiveRowTitle inputs,
                                  const SlopDeskWsCommandTitleBlock *blocks, size_t count,
                                  const uint8_t *strings, size_t strings_len,
                                  uint8_t *out, size_t cap);

// ---- The one ranking every search field asks for ----
//
// A candidate's fields ride as spans into the strings blob, `stride` of them per candidate in
// PRIORITY order, so one searchable field and three are the same door with a different number. The
// first field that matches decides both the score and the tier, and a lower tier always wins: the
// row CALLED Read Only outranks the row that merely mentions locking, whatever they scored.

typedef struct {
    size_t candidate_count;
    size_t stride;              // fields per candidate; 0 answers nothing
    bool   positions_wanted;    // false skips every backtrace
    size_t positions_tier;      // the ONE field the caller underlines
} SlopDeskWsSearchRankInputs;

typedef struct {
    size_t  candidate;
    size_t  tier;
    int32_t score;
    size_t  position_offset;    // into the `positions` array
    size_t  position_count;     // 0 for a row nothing underlines
} SlopDeskWsSearchRanked;

// Returns how many rows matched. A `cap` or `positions_cap` too small leaves BOTH buffers untouched
// and still reports both sizes, so one retry with the two numbers is always enough.
size_t slopdesk_ws_search_rank(SlopDeskWsSearchRankInputs inputs, const SlopDeskWsSpan *fields,
                               const uint8_t *strings, size_t strings_len,
                               const uint8_t *query, size_t query_len,
                               SlopDeskWsSearchRanked *out, size_t cap,
                               uint32_t *positions, size_t positions_cap,
                               size_t *positions_needed);
// Asked for rather than transcribed: a drifted copy lets one surface build rows the one beside it
// capped away.
size_t slopdesk_ws_max_search_results(void);

// ---- When the app is allowed to SPEAK ----
//
// Both enums cross as their CASE INDEX. A byte neither map below names reads as the quiet case —
// the system's own foreground behaviour, no cue — so a disagreement costs a notification rather
// than producing one nobody asked for.

typedef struct {
    uint8_t kind;         // 0 explicit OSC · 1 command finish · 2 watch finish
                          // · 3 agent task complete · 4 agent await input
    int32_t exit;         // the code, when `kind` is a command finish
    bool    exit_present; // false reads as a clean exit, whatever `exit` holds
} SlopDeskWsNotifyEvent;

typedef struct {
    bool    app_notifications_enabled;
    bool    notify_on_finish;
    bool    notify_on_error;
    bool    notify_on_watch_finish;
    uint8_t foreground;   // 0 off · 1 always · 2 only while the source tab is unfocused
    bool    agent_notify_task_complete;
    bool    agent_notify_await_input;
} SlopDeskWsNotifySettings;

// A token bucket, crossing by value in both directions.
typedef struct {
    double capacity;
    double refill_per_second;
    double tokens;
    double last_refill;
} SlopDeskWsNotifyRateLimiter;

bool     slopdesk_ws_notify_should_deliver(SlopDeskWsNotifyEvent event, bool app_active,
                                           bool source_pane_visible,
                                           SlopDeskWsNotifySettings settings);
uint32_t slopdesk_ws_notify_long_threshold_ms(void);
bool     slopdesk_ws_notify_is_long_running(uint32_t duration_ms);
// 0 no badge · 1 success · 2 failure
uint8_t  slopdesk_ws_notify_badge(int32_t exit, bool exit_present, uint32_t duration_ms,
                                  bool pane_focused, uint32_t long_threshold_ms);
bool     slopdesk_ws_notify_should_notify_completion(uint32_t duration_ms, bool pane_focused,
                                                     bool enabled, uint32_t long_threshold_ms);
// 0 silence · 1 task complete · 2 awaiting input
uint8_t  slopdesk_ws_notify_agent_sound(bool needs_input, bool sound_task_complete,
                                        bool sound_await_input);
bool     slopdesk_ws_notify_should_ring_bell(bool sound_shell_controlled);
bool     slopdesk_ws_notify_should_beep_on_error(int32_t exit, bool exit_present,
                                                 bool sound_on_error);
// The banner's title and body, written back to back; `title_len` says where the split is, so a
// title that contains any byte a separator could use is still read back whole.
size_t   slopdesk_ws_notify_explicit_content(const uint8_t *pane_title, size_t pane_title_len,
                                             const uint8_t *explicit_title, size_t explicit_title_len,
                                             const uint8_t *body, size_t body_len,
                                             uint8_t *out, size_t cap, size_t *title_len);
// The phrase an in-app card leads with, resolved from WHO spoke and WHAT happened together — the
// same flavour is "is done" for an agent and "finished" for a command.
// speaker: 0 agent · 1 command      flavour: 0 notice · 1 success · 2 failure · 3 attention
// A command's notice and its attention are returned VERBATIM: those two already carry their own
// wording, and an unrecognised byte on either axis lands on that pair.
size_t   slopdesk_ws_notify_toast_headline(uint8_t speaker, uint8_t flavour,
                                           const uint8_t *subject, size_t subject_len,
                                           uint8_t *out, size_t cap);
// Spends a token if there is one, writing the refilled bucket back through `limiter`.
bool     slopdesk_ws_notify_rate_limit_allow(SlopDeskWsNotifyRateLimiter *limiter, double now);
// Where a bucket comes FROM. The spend door above hands the bucket back by value, so the caller
// owns the four doubles between calls — which left one thing on this side of the boundary that
// is not an assignment: what a NEW bucket holds. A bucket that rests FULL delivers the first
// explicit notification after an attach; one that rests empty swallows it while it fills, which
// is a rate limiter behaving like a defect. `now` starts its clock.
SlopDeskWsNotifyRateLimiter slopdesk_ws_notify_rate_limiter(double capacity,
                                                            double refill_per_second, double now);
// The bucket the explicit OSC 9/777 path ships with. Its burst and its refill rate are the
// crate's, not a caller's default argument: those two numbers ARE the anti-flood policy, and a
// second spelling of them is a second opinion about how much a hostile shell may post — of which
// the looser one is always the one that runs.
SlopDeskWsNotifyRateLimiter slopdesk_ws_notify_explicit_rate_limiter(double now);

// ---- What the window's CHROME shows around the panes ----
//
// Two of these have a rung that means NO OPINION, and each says so in the way its own answer allows:
// the sidebar's is -1 beside the booleans 0 and 1, the Dock's is a `present` flag beside its
// fraction. A refusal has to sit outside the range of every real answer, or it is read as one.
// Every enum here crosses as a case index, and an unrecognised byte reads as the quiet case.

typedef struct {
    bool collapsed;
    bool manual_override;    // the user's own ⌘⇧L or swipe put it where it is
    bool last_auto;          // read only when `last_auto_present`
    bool last_auto_present;  // false is the first application — which counts as a regime edge
} SlopDeskWsSidebarState;

typedef struct {
    bool   tinted;
    bool   animates;
    double fraction;         // read only when `fraction_present`
    bool   fraction_present; // false is the indeterminate spinner
} SlopDeskWsDockTile;

// `mode` is 0 never auto-hide · 1 always shown · 2 auto. 1 collapse · 0 reveal · -1 no opinion.
int32_t slopdesk_ws_sidebar_desired_collapsed(uint8_t mode, size_t tab_count);
// The flags the chrome should hold afterwards. Actuation is gated on the 1↔>1 tab-count EDGE, so a
// manual collapse survives an unrelated tab opening within the same regime.
SlopDeskWsSidebarState slopdesk_ws_sidebar_apply_auto_hide(uint8_t mode, size_t tab_count,
                                                           SlopDeskWsSidebarState state);
// `policy` is 0 while a process runs · 1 always · 2 more than one tab.
bool slopdesk_ws_close_should_confirm(uint8_t policy, bool is_busy, size_t tab_count);
// `rollup` is the WIRE's own OSC 9;4 discriminant — 1 in progress · 2 error · 3 indeterminate;
// 0 (clear) and anything else is the absence of a rollup.
SlopDeskWsDockTile slopdesk_ws_dock_tile(uint8_t rollup, uint8_t percent, bool any_failure,
                                         bool animate_enabled, bool error_badge_enabled);

/* Who owns the TOP EDGE in borderless fullscreen — the dwell-gated Parallels model, recorded in
 * docs/DECISIONS.md 2026-07-22. In a fullscreen remote desktop the pointer at the very top must
 * reach the REMOTE menu bar first, but macOS's own auto-hide reveals the LOCAL one on a bare touch
 * and steals the click. So a passing touch stays remote; holding the edge for the dwell is the
 * deliberate "I want my Mac's menu bar" gesture.
 *
 * The gate crosses BY VALUE both ways: it is five numbers with no interior, and a fold that returns
 * the next gate cannot leave a stale one behind for a later pointer move to read. `pointer_y_from_
 * top` is DISTANCE FROM THE SCREEN'S TOP EDGE in points (0 = pressed against it), so the one
 * coordinate flip stays with the window layer that owns the screen; the clock is an argument, so
 * nothing behind the door reads one.
 *
 * Fold on every pointer move AND once at `slopdesk_ws_dwell_deadline` — a motionless pointer emits
 * no further moves, so the dwell can only complete on a timer re-feeding the last position.        */
#define SLOPDESK_WS_DWELL_HIDDEN   0u
#define SLOPDESK_WS_DWELL_ARMING   1u
#define SLOPDESK_WS_DWELL_REVEALED 2u

typedef struct {
    uint8_t phase;                // one of SLOPDESK_WS_DWELL_*
    double  since;                // when the running dwell started — read only while ARMING
    double  dwell_seconds;        // the hold this gate demands
    double  reveal_zone_points;   // the arming zone, from the top edge
    double  conceal_zone_points;  // the conceal zone — wider, so the revealed bar does not flicker
} SlopDeskWsDwellGate;

SlopDeskWsDwellGate slopdesk_ws_dwell_gate(void);
SlopDeskWsDwellGate slopdesk_ws_dwell_update(SlopDeskWsDwellGate gate, double pointer_y_from_top,
                                             double now);
// False means nothing is arming — no timer to schedule — and then `*out` is untouched.
bool slopdesk_ws_dwell_deadline(SlopDeskWsDwellGate gate, double *out);

// ---- What the sidebar SHOWS, in what order, under which labels ----
//
// Both list doors answer in the CALLER's indices: a rail row is an id, a kind, a badge, a selection
// flag and half a dozen strings, almost none of which decides where it goes, so the answer names
// rows and the near side reorders the array it already holds.

typedef struct {
    SlopDeskWsSpan title;
    SlopDeskWsSpan subtitle;
    // Never drawn, always searchable: a git-repo row shows its git line where its path would be, so
    // without the raw cwd it could not be found by path at all.
    SlopDeskWsSpan cwd;
    SlopDeskWsSpan process_label;
} SlopDeskWsRailRowFields;

// `tab_rank` is where the row's tab sits in the display order; SIZE_MAX for a tab absent from it,
// which sorts last without dropping the row.
typedef struct {
    SlopDeskWsSpan project_key;
    size_t         tab_rank;
} SlopDeskWsRailPlanRow;

typedef struct {
    size_t row_index;
    size_t section;
} SlopDeskWsRailPlacement;

// A label that may collide with an identical one, and the path it was derived from — a row's title
// and its cwd, or a section's header and its project key. ONE rule breaks both.
typedef struct {
    SlopDeskWsSpan text;
    SlopDeskWsSpan source;
} SlopDeskWsRailLabel;

bool slopdesk_ws_rail_row_matches(SlopDeskWsRailRowFields fields, const uint8_t *strings,
                                  size_t strings_len, const uint8_t *query, size_t query_len);
// Returns how many placements there ARE, which is always `count`. A short `cap` writes nothing and
// returns the same number, so the retry is §4's.
size_t slopdesk_ws_rail_plan(const SlopDeskWsRailPlanRow *rows, size_t count,
                             const uint8_t *strings, size_t strings_len,
                             SlopDeskWsRailPlacement *out, size_t cap);
// What every item should be CALLED once identical labels have been told apart, for the WHOLE list
// in one delivery: `count` entries in list order, each a four-byte big-endian length then that many
// UTF-8 bytes. A zero length is "keep the label you have" — a qualified label is never empty, so
// the two never collide. A return larger than `cap` means nothing was written; ask again at that
// size.
//
// A collision is a fact about the LIST, so answering for one member needs the whole list in hand: a
// per-index face would take this same array and this same blob and throw the rest of the answer
// away, which is what the caller used to pay for, rebuilding the list on every index — `n` label
// arrays and `n` copies of every title's bytes to answer `n` questions that share one input.
size_t slopdesk_ws_rail_disambiguated_labels(const SlopDeskWsRailLabel *items, size_t count,
                                             const uint8_t *strings, size_t strings_len,
                                             uint8_t *out, size_t cap);
// ---- The rail's structural FINGERPRINT ----
//
// The sidebar memoizes its row model against a fingerprint of the workspace's structure, and the
// fingerprint is evaluated on EVERY render pass and every keystroke — hit or miss, because
// comparing it is what decides which. So its walk is the walk the memo pays for itself, and per
// pane it asked two questions that are each several rules deep: the By-Project key's
// transient-plugin guard, and whether the title chain would come off the pane's foreground process.
//
// The crossings were never the cost — a bare door is about a nanosecond. The MARSHALLING was:
// asking per pane meant a heap allocation per string per question, the cwd lent twice to two
// different doors and each answer copied out through a scratch buffer into a `String` nobody keeps.
// The list door lends every string once, out of one blob, and answers all of it in one buffer.

// The fields that pick a pane's title RUNG, with the project key ALREADY RESOLVED.
//
// Deliberately not `SlopDeskWsRailStructurePane` though the layout matches: that one carries the
// key the HOST pushed, before the precedence runs, and this one carries the key the pane was FILED
// under. A surface with no section headers passes none at all and gets the folder name, which is
// the same rule with nothing to subtract — and a struct that let the two be passed for each other
// would make an at-root pane out of every pane on that surface, with nothing but a comment to
// catch it.
typedef struct {
    uint8_t        kind;
    SlopDeskWsSpan spec_title;
    bool           user_renamed;
    SlopDeskWsSpan cwd;
    SlopDeskWsSpan project_key;
} SlopDeskWsRailTitleShape;

// One pane as the fingerprint reads it. `host_project_key` is what the host pushed, BEFORE the
// precedence runs; `spec_title` absent is a pane with no spec at all, which is a different fact
// from a spec whose title is blank.
typedef struct {
    uint8_t        kind;
    SlopDeskWsSpan spec_title;
    bool           user_renamed;
    SlopDeskWsSpan cwd;
    SlopDeskWsSpan host_project_key;
} SlopDeskWsRailStructurePane;

// Whether this pane's structural title would come off its foreground PROCESS. The near side reads
// its volatile process dictionary only where this is true, so the answer decides an Observation
// dependency and not just a string. Kept for the three callers that genuinely want ONE answer —
// the window title and the two Open-Quickly pickers, which ask about the pane under the cursor.
bool slopdesk_ws_rail_titles_by_process(SlopDeskWsRailTitleShape shape, const uint8_t *strings,
                                        size_t strings_len);
// Both fingerprint answers for every pane, in one delivery: `count` entries in the caller's order,
// each a titles-by-process flag byte, a key-PRESENCE byte, a four-byte big-endian length and that
// many UTF-8 bytes. A return larger than `cap` means nothing was written; ask again at that size.
//
// The presence byte is §4b's rule and it is load-bearing here — a pane whose cwd is the empty
// string resolves to a project key that is present and blank, which buckets differently from a
// pane with no key at all, and a length alone could not say which.
size_t slopdesk_ws_rail_structure_keys(const SlopDeskWsRailStructurePane *panes, size_t count,
                                       const uint8_t *strings, size_t strings_len,
                                       uint8_t *out, size_t cap);

// The minimum flex weight a divider may take, from the crate that enforces it — `repaired()`
// clamps to this number, so a transcribed copy would describe a rule the client does not share.
double slopdesk_ws_min_weight(void);

// The deepest nesting a layout may KEEP. Its neighbour above was asked for through a door while
// this one was written down again on the Swift side as a bare 12, which docs/55 §8 names as the
// anti-pattern it is: two numbers with one meaning, the second right only until somebody tunes the
// first. Three rules clamp to it — the persisted split tree's decode, the template layout's repair,
// and the solver recursion both feed.
size_t slopdesk_ws_max_depth(void);

// The schema version the persisted workspace shape writes, and the one a load compares against.
// There is no migration behind that comparison, so two spellings of it agree right up until one is
// bumped alone — after which one side sets aside every file the other just wrote.
int64_t slopdesk_ws_schema_version(void);

// The longest a string field may be. `slopdesk_ws_encode_string` takes the bound as an argument,
// because a field's own limit is not always the protocol's — a renameTab name is clamped tighter
// than a title — so a caller with no tighter limit asks for the protocol's here.
size_t slopdesk_ws_max_string_bytes(void);

// ---- The project header's git DIALECT — `slopdesk_workspace::git_line` ----
//
// `main ↑2 ↓1 +3 !4 ?5 ~1 $2` is a language, not a label: the branch first, then only the NON-ZERO
// sigils in a fixed order, each with a role that decides its ink and its weight, and a shedding
// ladder for the widths a real sidebar column actually offers.
//
// No TEXT crosses. A run is a role, one glyph and a number, so the near side spells `↑` beside `2`
// where it is already laying out glyphs — but it never CHOOSES the glyph. A dead second Swift
// renderer once spelled a conflict `=` against this dialect's `~`, and both compiled for months.
//
// The branch is the one run with no sigil: it is a NAME, which is why it truncates rather than
// compacting, and why its text is the caller's own string. `detached` on that run says the far side
// had no branch to name.

// The most runs one line can have — the branch plus one per non-zero count.
#define SLOPDESK_GIT_MAX_RUNS 8
#define SLOPDESK_GIT_INK_BRANCH 0
#define SLOPDESK_GIT_INK_DIVERGENCE 1
#define SLOPDESK_GIT_INK_STAGED 2
#define SLOPDESK_GIT_INK_MODIFIED 3
#define SLOPDESK_GIT_INK_UNTRACKED 4
#define SLOPDESK_GIT_INK_CONFLICTED 5
#define SLOPDESK_GIT_INK_STASH 6
#define SLOPDESK_GIT_WEIGHT_REGULAR 0
#define SLOPDESK_GIT_WEIGHT_SEMIBOLD 1
#define SLOPDESK_GIT_WEIGHT_BOLD 2
// What `sigil` holds for the branch. Tested BEFORE any decode: NUL is a scalar like any other, so a
// `UnicodeScalar(0)` is a real character and would spell the branch as a blank.
#define SLOPDESK_GIT_NO_SIGIL 0

typedef struct {
    bool     has_repo;
    bool     detached;
    uint32_t ahead;
    uint32_t behind;
    uint32_t staged;
    uint32_t modified;
    uint32_t untracked;
    uint32_t conflicted;
    uint32_t stash;
} SlopDeskGitCounts;

typedef struct {
    uint8_t  ink;
    // Carried alongside the role so a caller laying out one run never asks twice about it.
    uint8_t  weight;
    uint32_t sigil;
    uint32_t count;
    bool     detached;
} SlopDeskGitRun;

// Both doors write at most `cap` runs and return how many the line HAS — §4's protocol at a size
// that never needs the retry, since `SLOPDESK_GIT_MAX_RUNS` bounds it structurally.
size_t slopdesk_git_line_runs(const SlopDeskGitCounts *counts, SlopDeskGitRun *out, size_t cap);
// The READOUT alone — the branch dropped — after giving up `level` rungs of the shed ladder. Folded
// from the same counts rather than from a run array handed back: the counts are three words the
// caller already holds, and a returned array would have to be validated field by field to be
// trusted.
size_t slopdesk_git_line_shed(const SlopDeskGitCounts *counts, size_t level, SlopDeskGitRun *out,
                              size_t cap);

// ---- Where the highlight goes — `slopdesk_workspace::list_nav` ----
//
// The rows never cross: each rule reads a COUNT and answers an INDEX into the list the caller
// already holds. Three overlays — the picker, the command navigator and the palette — each carried
// their own copy of the clamp, which is why it is one door.
//
// A LIST clamps and a RING wraps: arrowing past the last row leaves the highlight there, the way
// every macOS list behaves, while Tab through the filter pills comes back around because a ring has
// no ends to sit against.

// Moved by `delta`, clamped to [0, count - 1]. Any count <= 0 answers 0 — the index every one of
// those surfaces stores while it has nothing selected. The add saturates, so a page key over a
// two-row list, and an i64 extreme from a caller, both stay indices.
int64_t slopdesk_list_clamped_selection(int64_t current, int64_t delta, int64_t count);
// The 0-based row a ⌘1–9 chord names. -1 for ⌘0 (a filter chord, never a pick), for a chord above
// nine, and for a chord past the rows on screen.
int64_t slopdesk_list_quick_pick(int64_t one_based, size_t row_count);
// `delta` steps around a ring of `count`, wrapping at both ends. -1 for an empty ring, and for a
// starting index that is not in it — there is nothing to step from, and inventing a first entry
// would move a selection nobody asked to move.
int64_t slopdesk_list_wrapped_index(size_t index, int64_t delta, size_t count);

// ---- Which projection the app draws, and where a new pane starts ----
//
// `window_width` is read only when `window_width_present`: the outer window and the detail column
// are compared against DIFFERENT thresholds, so an absent window is not a window of the detail's
// width. Collapse the two and the macOS floor window resolves compact for one frame on every launch.
bool slopdesk_ws_is_compact(bool size_class_compact, double detail_width,
                            double window_width, bool window_width_present);
// 0 phone · 1 pad · 2 mac. A compact size class forces the phone tier even on a pad idiom.
uint8_t slopdesk_ws_video_device_class(bool is_mac, bool size_class_compact, bool idiom_pad);
// How many live video panes that class decodes at once. An unrecognised class is the phone floor.
size_t slopdesk_ws_video_cap(uint8_t device_class);

// The `working-directory` config: 0 inherit · 1 home · 2 a path, with the TRIMMED path written to
// `(out, cap)` and its length reported in `needed`. The kind is the return because two of the three
// answers name no path at all, which §4's `0` could not tell apart from a refusal.
uint8_t slopdesk_ws_workdir_parse(const uint8_t *raw, size_t len,
                                  uint8_t *out, size_t cap, size_t *needed);
// The parse door's inverse: the stored config string for kind 0 or 1, `0` for kind 2 — a path's
// config string is the path the caller already holds. The keywords live on one side only.
size_t slopdesk_ws_workdir_keyword(uint8_t kind, uint8_t *out, size_t cap);
// Which string the new pane's cwd comes from: 0 neither · 1 the configured path · 2 the active
// pane's cwd. `kind` is the parse door's answer; anything else reads as home, which names no
// directory. Nothing is copied back — every caller already holds both strings.
uint8_t slopdesk_ws_workdir_source(uint8_t kind, bool active_cwd_known);

// ---- What Settings offers ----
//
// A settings page is two things stacked: a control, which is a view and belongs to whichever
// framework is drawing, and the ANSWER to "what can this be set to, what is each choice called,
// what does the number read as" — which is the same on a phone as on a Mac and is not a view at
// all. Every door here is the second thing.
//
// An option GROUP crosses whole, because a group is what every caller asked for. It used to be a
// count plus four indexed field accessors, and the near side's only reader of any of them built the
// whole group — so naming one token cost `1 + 4n` crossings, and the phone's all-settings list paid
// that inside a `ForEach` on every keystroke and on every settings write. Twenty-three groups
// holding sixty-seven options came to 291 crossings for a table that is `&'static` over there. The
// five doors are DELETED rather than kept beside the new one: a door nothing calls is a second way
// to ask what a live door already answers.
//
// What kept an indexed door is the answer that is genuinely ONE string — a density token by name,
// an apply-timing chip's words, a ladder stop's label — each of which a caller reads once into a
// `static let`.
//
// EVERY OPTION CROSSES AS THE VALUE THE STORE PERSISTS, never as a case index. The near side
// rebuilds its own enum from the token with the `RawRepresentable` init it already has, so
// inserting a case in either language cannot silently re-point a row at a different value.

// The GROUPS, in case-index order. One control's worth of choices each.
#define SLOPDESK_SETTINGS_GROUP_CURSOR_STYLE           ((uint8_t)0)
#define SLOPDESK_SETTINGS_GROUP_NEW_TAB_POSITION       ((uint8_t)1)
#define SLOPDESK_SETTINGS_GROUP_DENSITY                ((uint8_t)2)
#define SLOPDESK_SETTINGS_GROUP_WINDOW_SIZE            ((uint8_t)3)
#define SLOPDESK_SETTINGS_GROUP_DESKTOP_PRESENTATION   ((uint8_t)4)
#define SLOPDESK_SETTINGS_GROUP_OPTION_AS_ALT          ((uint8_t)5)
#define SLOPDESK_SETTINGS_GROUP_RIGHT_CLICK_ACTION     ((uint8_t)6)
#define SLOPDESK_SETTINGS_GROUP_ON_LAUNCH              ((uint8_t)7)
#define SLOPDESK_SETTINGS_GROUP_CLOSE_CONFIRMATION     ((uint8_t)8)
#define SLOPDESK_SETTINGS_GROUP_CLOSE_CONFIRMATION_TAB ((uint8_t)9)

// The LADDERS — sliders with magnitude stops on them.
#define SLOPDESK_SETTINGS_LADDER_SCROLLBACK        ((uint8_t)0)
#define SLOPDESK_SETTINGS_LADDER_SCROLL_MULTIPLIER ((uint8_t)1)
#define SLOPDESK_SETTINGS_LADDER_BUSY_DELAY        ((uint8_t)2)

// When a setting takes effect, as a DATA attribute so the distinction can be a chip not prose.
#define SLOPDESK_SETTINGS_TIMING_LIVE      ((uint8_t)0)
#define SLOPDESK_SETTINGS_TIMING_RECONNECT ((uint8_t)1)

// ONE option group's choices, in render order, in ONE delivery. `0` is "there is no such group" —
// a group index no group has — and a group with no options would still deliver its two-byte header,
// so §4's `0` keeps its literal meaning. All lengths are big-endian, because this is read across a
// C boundary where a width that followed the target would be a bug waiting for a 32-bit build.
//
//   [u16 option_count]
//   option_count x 4 x [u32 length][UTF-8 bytes]
//
// The four fields per option are `token`, `label`, `caption`, `menu_label`, in that order. The
// token is what the store PERSISTS. The caption is the honesty channel and a ZERO LENGTH IS NO
// CAPTION — not an empty one — which is the reading the deleted per-field door already had, since a
// choice with an empty caveat and a choice with none render identically. `menu_label` is the
// one-line form a MENU shows, the label with the caveat folded in after an en dash: the fold is a
// rule, and a rule re-concatenated on the near side is two rules, so it is composed over here and
// rides the same delivery.
//
// Their number is derivable from the header, which is what lets the near side cut them with the
// length-prefixed splitter the settings-layout page already uses and PAD to the promised count: a
// short delivery is a layout disagreement between the two sides, and padding is what stops it
// becoming a silent off-by-one where every option after the gap wears its neighbour's words.
size_t slopdesk_settings_option_group(uint8_t group, uint8_t *out, size_t cap);

// The DENSITY group's two tokens, by name. It is the one group the store persists as a bare string
// rather than through an enum, so without this the near side would spell `"compact"` itself.
size_t slopdesk_settings_density_token(bool compact, uint8_t *out, size_t cap);

// The 8-section taxonomy — one row in the Mac's navigator, one row in the phone's list, one order.
size_t slopdesk_settings_section_count(void);
size_t slopdesk_settings_section_id(size_t index, uint8_t *out, size_t cap);
size_t slopdesk_settings_section_title(size_t index, uint8_t *out, size_t cap);
size_t slopdesk_settings_section_symbol(size_t index, uint8_t *out, size_t cap);

// ---- Which settings sections a needle names ----
//
// The taxonomy has crossed this boundary since it was written — a count and three indexed field
// accessors, just above. The SEARCH over it never did, so each face held the list from here and then
// wrote its own case-insensitive containment rule to filter it, four times over. That is docs/55 §8's
// drift class in its cleanest form, and §8's point is that this class is not ranked by cost: eight
// sections filtered per keystroke is ~750 ns and would never on its own justify a crossing. What
// justifies it is that "which sections does this needle name" stops having two answers.
//
// `out[i]` indexes the same list the three accessors above are indexed by, ascending, so the answer
// arrives in render order. The needle crosses RAW — the far side folds ASCII case itself, so a caller
// neither lowercases nor trims first, which is what keeps the rule from being spelled a fifth time.
// Returns how many matched; a blank needle matches the whole taxonomy, which is a search field's zero
// state. `cap` below that count leaves `out` untouched and reports the same number, the §4 retry —
// though the caller derives its size from the section count, so it never runs.
//
// The fold is ASCII-only, deliberately, and that is NOT what a locale-aware containment does: the
// system one normalises and case-folds, so it holds `file` in `ﬁle` and `strasse` in `straße`. It
// does NOT fold diacritics — `Café` does not hold `cafe`; only `localizedStandardContains` reaches
// that far. The two agree on ASCII and only on ASCII. Every section title is ASCII and the crate pins
// that in a test beside the rule, so the substitution is exact here — it is not a general
// replacement for searching user text.
size_t slopdesk_settings_sections_matching(const uint8_t *needle, size_t needle_len,
                                           uint32_t *out, size_t cap);

// The apply-timing chip.
size_t slopdesk_settings_timing_label(uint8_t timing, uint8_t *out, size_t cap);
size_t slopdesk_settings_timing_symbol(uint8_t timing, uint8_t *out, size_t cap);

// A ladder's range and granularity. `known` false leaves the three numbers at zero.
typedef struct {
    double min;
    double max;
    double step;
    bool   known;
} SlopDeskSettingsLadder;
SlopDeskSettingsLadder slopdesk_settings_ladder(uint8_t ladder);
// Its magnitude stops — the values a user actually picks, not an even subdivision of the range. A
// stop that does not exist reports NaN rather than zero, because zero IS a legitimate stop.
size_t slopdesk_settings_ladder_preset_count(uint8_t ladder);
double slopdesk_settings_ladder_preset_value(uint8_t ladder, size_t index);
size_t slopdesk_settings_ladder_preset_label(uint8_t ladder, size_t index, uint8_t *out, size_t cap);
// What the slider's current value reads as. Each ladder's readout is about its own unit: scrollback
// is thousands-grouped with a NARROW NO-BREAK SPACE (never a locale comma — the readout is
// monospaced digits, where a comma reads as a decimal point in half the world), the multiplier
// carries two decimals to match its own step, and the delay says `Instant` at zero because that is
// the BEHAVIOUR changing rather than a delay that happens to be short.
size_t slopdesk_settings_ladder_readout(uint8_t ladder, double value, uint8_t *out, size_t cap);

// A stepper range's ends and granularity — the ladder's sibling, for a value whose useful settings
// are not a handful of magnitudes but any literal count in the range. `known` false leaves the three
// numbers at zero. The pixel step is fifty because one pixel at a time across sixteen thousand is a
// control that cannot reach its own far end.
typedef struct {
    int64_t min;
    int64_t max;
    int64_t step;
    bool    known;
} SlopDeskSettingsStepper;
SlopDeskSettingsStepper slopdesk_settings_stepper(uint8_t stepper);
// What the value reads as after the row's label — `80`, `1000 px`, `13.5`. A whole value drops its
// fraction; a fractional one prints as it is. The UNIT used to cross instead, so that each side
// could compose from the value it holds — and both did, with only one of them dropping the
// fraction. A double argument costs nothing and leaves one composition.
size_t slopdesk_settings_stepper_readout(uint8_t stepper, double value, uint8_t *out, size_t cap);

// ---- Every setting as a ROW ----
//
// The other half of the same page: one entry per configuration key, carrying the one label and the
// one description that key uses wherever it appears — in the searchable all-settings list AND in the
// section control that edits it. Those were two byte-identical copies in two targets before this.
//
// The KEY is what the near side holds (they are `Defaults.Key` names), so a row is reached by key as
// often as by position — `slopdesk_settings_row_index` turns one into the other.

#define SLOPDESK_SETTINGS_ROW_BUCKET_ADVANCED_ONLY 0
#define SLOPDESK_SETTINGS_ROW_BUCKET_HAS_DEDICATED_TAB 1
// What `slopdesk_settings_row_index` answers for a key no row has. A sentinel rather than a zero,
// because zero is a real row.
#define SLOPDESK_SETTINGS_ROW_NONE SIZE_MAX

size_t slopdesk_settings_row_count(void);
size_t slopdesk_settings_row_key(size_t index, uint8_t *out, size_t cap);
bool slopdesk_settings_row_is_inline_editable(size_t index);
// WHERE a row's value lives, and so what restores it: `0` a `UserDefaults` key a global reset
// reaches, `1` a device-local fact in `device-prefs.json`, `2` a typed render field (or the density
// token) that comes back with its model. A FIELD on every row rather than two lists beside the
// table, because a list is a second spelling that drifts silently: a new row is simply absent from
// it, which reads as `0` and is wrong for exactly the rows a defaults reset misses. `0` past the
// end.
uint8_t slopdesk_settings_row_persistence(size_t index);
// Whether the half that identifies as `mac` advertises this row. DERIVED from the page table below,
// never declared here: which half can edit a setting is already a `Platform` on a group and on a
// row, and a second spelling of it would agree until somebody moved a group. A row the page table
// names nowhere — one a bespoke surface edits — is advertised on both. `false` past the end.
//
// The index used to advertise every key on both halves, on the grounds that a key still round-trips
// on iOS. What that shipped was a live switch over `notifications.bounceDock` that no Dock reads and
// a ✎ into an Appearance page with no Dock Icon group on it. `shown` rather than `platform` here for
// the palette table's reason: the near side must not turn its own slice back into an `#if`.
bool slopdesk_settings_row_shown(size_t index, bool mac);
size_t slopdesk_settings_row_index(const uint8_t *key, size_t key_len);
// The positions a query matched, under the same retry protocol as the string doors: a return larger
// than `cap` means nothing was written — ask again at that size.
size_t slopdesk_settings_row_matches(const uint8_t *query, size_t query_len, size_t *out, size_t cap);
// A WHOLE row in one delivery: the bucket byte, then seven fields, each a four-byte big-endian
// length followed by that many UTF-8 bytes — key, label, page label, description, default text,
// target section, keywords. The same retry protocol; `0` for an index no row has.
//
// A zero-length field is an ABSENT one. That is how target section says "edited in place" and how
// keywords says the row needs no extra searchable text. The page label is the page register where
// the row carries an override and the index register otherwise, so a caller never has to know which
// rows have one. The bucket byte takes the values the two BUCKET macros above name.
//
// It exists because the match already crosses as positions to keep a filter one crossing rather
// than one per field per row, and the reader then turned each position back into eight calls. On
// every settings-search keystroke. The seven per-field doors it replaced were DELETED rather than
// left standing beside it: once the reader had this one, nothing called them, and an exported door
// with no caller is a second way to ask what a live door already answers — the drift docs/55 §8 is
// about.
size_t slopdesk_settings_row_fields(size_t index, uint8_t *out, size_t cap);

// ---- Which half lists a command-palette VERB ----
//
// The same "a platform gate is DATA" rule as the settings table below, applied to the one surface
// whose whole job is to tell the user what the app can do. Every actuator on the palette's
// coordinator defaults to an empty closure and a `.store` row's run arm may be a macOS-only `#if`
// with nothing in the else, so a row that is listed and INERT is indistinguishable from one that ran
// and had nothing to do. Three of the phone's rows were exactly that.
//
// `shown` rather than `platform` on purpose: the near side already knows which slice it is, and what
// it must never do is turn that back into an `#if` around a row. The count/index pair exists so a
// test can walk this table and prove it names the same verbs the Swift catalog does — an id declared
// on only one side is the failure that would put the hole back.
//
// An id no row declares is SHOWN. A typo must not delete a row without a word;
// `scripts/check-supervisor.sh` is what makes an undeclared id impossible.
bool slopdesk_palette_row_shown(const uint8_t *id, size_t len, bool mac);
size_t slopdesk_palette_row_count(void);
size_t slopdesk_palette_row_id(size_t index, uint8_t *out, size_t cap);

// ---- Which half lists a KEYBINDING ----
//
// The same rule one surface further in. The registry behind these rows is not one list — it is the
// cheat sheet, the keybindings editor, the `ctl` verb list, and the CHORD TABLE the dispatcher
// resolves against. That last one is why a listed-and-inert binding is worse than a listed-and-inert
// palette row: a bound chord does not reach the terminal, so ⌥⌘P was taken away from the PTY to run
// a macOS-only `#if` with nothing in its else. Dropping the row drops the chord, and the key falls
// through to the pane the way an unbound chord should.
//
// A SECOND table rather than a shared one because these are two id spaces over two vocabularies with
// partial overlap in both directions (`pane.detach` here is `action.detachPane` there; ~45 rows here
// have no palette entry at all). Each table is complete over its own space and pinned to its own
// Swift list; a shared one would be a join maintained by hand.
//
// An id no row declares is SHOWN, for the same reason as above.
bool slopdesk_binding_row_shown(const uint8_t *id, size_t len, bool mac);
size_t slopdesk_binding_row_count(void);
size_t slopdesk_binding_row_id(size_t index, uint8_t *out, size_t cap);

// ---- The keybindings editor's search filter ----
//
// The editor filters the whole registry on every keystroke, and until this entry existed it did so
// with `lowercased().contains(_:)` per field per row. That is the wrong primitive and Swift has no
// cheap one: measured against the shipped xcframework, `lowercased()` is 94ns and the `contains`
// over its result is 825ns for a 35-byte title and 1,652ns for a 70-byte keyword run — grapheme-
// aware search over text that is ASCII. The same containment as a byte scan is 29ns and 53ns.
// Four spellings across eighty-five rows came to 415us per keystroke.
//
// The ROWS are lent rather than held on the far side, which is the one thing here that is not the
// settings table's shape. A binding's title and keywords are written beside the `WorkspaceAction`
// case the row routes to; moving them across would put a crossing in front of every cheat-sheet,
// menu and palette row that reads a title today. So the caller marshals its four spellings per row
// into one blob and this answers which rows a query keeps.
//
// `records` is `[u32 count]`, then `count` records, each `[u8 field_count]` then that many
// `[u32 len][len bytes]` fields, little-endian. A binding lends four: title, keyword run, chord
// glyph, chord canonical — the last two empty for a row with no chord. The answer is POSITIONS in
// that list, the way the settings filter answers positions in its own table.
//
// `needed > cap` means nothing was written; ask again at that size. `0` is no row matched, which is
// also what a non-UTF-8 query and a torn record list answer — all three end at an empty list, and
// the near side writes the list itself, so a fourth reading would be a distinction no caller could
// act on.
size_t slopdesk_ws_binding_row_matches(const uint8_t *query, size_t query_len,
                                       const uint8_t *records, size_t records_len,
                                       size_t *out, size_t cap);

// ---- The SHAPE of a settings page ----
//
// Which groups a page shows, in what order, what each row is, and — the reason this table exists —
// which platform each of those belongs to. A platform gate is DATA here: the Mac renderer asks with
// `mac = true` and the phone with `mac = false`, and NEITHER carries an `#if`.
//
// `mac` is an argument rather than the compiled slice on purpose. The xcframework is built per
// slice, so the table could have been filtered by `cfg!` — but then "which groups does the phone
// show" would be unanswerable on a Mac, and that is exactly what the tests on both sides ask.
//
// A PAGE crosses whole, in one delivery. It used to cross positionally — a group count, then a
// title, a timing and a row count per group, then six more doors per row — which cost `1 + 3G + 6R`
// crossings to answer one question, and both renderers ask it from inside a body they re-evaluate
// whenever a setting on the page changes. Worse, every one of those calls re-derived the whole
// page to reach one member: the row accessor filters the flat table into a fresh list and then
// filters that group's rows into a second one, so Appearance's ~166 crossings did ~166 filters and
// ~330 allocations to read 23 rows. The near side wanted the page, so the page is what crosses.
//
// The rows and groups are still filtered to the asking half before anything is written, so a phone
// reading the fourth group of General gets its own fourth group, never a hole where a macOS-only
// group was. The near side never sees the unfiltered table and cannot render from it.
//
// The answer, all lengths big-endian because this is read across a C boundary where a width that
// followed the target would be a bug waiting for a 32-bit build:
//
//     [uint16 group_count][uint16 row_total]
//     group_count x [uint8 timing][uint16 row_count]
//     row_total   x [uint8 control_kind][uint8 control_argument]
//     (group_count + 4 * row_total) x [uint32 length][UTF-8 bytes]
//
// The strings ride BEHIND the fixed records rather than interleaved with them, and how many there
// are follows from the header — group titles in group order, then key, subtitle, glyph and bespoke
// id per row, rows in page order. That is what lets the reader cut them with the same
// length-prefixed splitter the rail's disambiguated labels use and PAD to the promised count: a
// short delivery is a layout disagreement between the two sides, and padding is what stops it
// becoming a silent off-by-one where every row after the gap renders its neighbour's words.
//
// A zero length is NO string, not an empty one — a row with no glyph and a row with an empty one
// draw identically, so a presence flag would name a distinction nothing downstream can act on. The
// ten doors this replaced already conflated them, which is what keeps this a marshalling change.
//
// `0` means there is no such page: a section index no section has. A return larger than `cap` means
// nothing was written — ask again at that size. Every page fits 4096 bytes today (the widest is
// Controls on a Mac at 3676), and a Rust test fails if one ever stops fitting, so the retry is a
// correctness property rather than a second crossing every settings render pays.
//
// Control kinds, as the `control_kind` byte of each row record carries them.
#define SLOPDESK_SETTINGS_CONTROL_TOGGLE  0
#define SLOPDESK_SETTINGS_CONTROL_MENU    1
#define SLOPDESK_SETTINGS_CONTROL_CARDS   2
#define SLOPDESK_SETTINGS_CONTROL_SLIDER  3
#define SLOPDESK_SETTINGS_CONTROL_STEPPER 4
#define SLOPDESK_SETTINGS_CONTROL_TEXT    5
// Prose belonging to the group rather than to a setting; its words are the row's subtitle.
#define SLOPDESK_SETTINGS_CONTROL_NOTE    6
#define SLOPDESK_SETTINGS_CONTROL_BESPOKE 7
// What a row's `control_argument` byte reads as where its kind draws over neither an option group
// nor a scalar ladder.
#define SLOPDESK_SETTINGS_LAYOUT_NONE ((uint8_t)0xFF)
size_t slopdesk_settings_layout_page(uint8_t section_index, bool mac, uint8_t *out, size_t cap);

// ---- What the phone's keyboard sends ----
//
// A touch device is forced to split physical input in two: the keys a terminal needs raw, and
// anything a multi-stage composition could be part of. Every door below is one side or the other of
// that split, and none of them holds the terminal's mode — the caller reads that off the live model
// per press, because the program that set it is on the far side of the PTY.
//
// The flag word IS `KeyChord.Modifiers`' own bits 0-3, so a chord's modifiers cross back out
// untranslated. Nothing above them is a modifier: which keys are special is a rule, and it is
// answered on the far side from `hid_usage`.
#define SLOPDESK_PHONE_KEY_SHIFT   (1u << 0)
#define SLOPDESK_PHONE_KEY_CONTROL (1u << 1)
#define SLOPDESK_PHONE_KEY_OPTION  (1u << 2)
#define SLOPDESK_PHONE_KEY_COMMAND (1u << 3)
// Bits 4-5 are the one thing in this word that is not a modifier: `controls.optionAsAlt`, which is a
// property of the KEYBOARD rather than of the press, and the only setting either encoding door
// reads. It rides the word that already crossed because a new parameter would change the signature
// of two doors for a value neither caller computes per-press.
//
// BOTH is ZERO on purpose, and it is the one value here that is not free to be reordered: these bits
// EXTEND a word that had four, so an absent pair has to read as what the doors did before the pair
// existed, which was to treat the Option key as Alt/Meta unconditionally. Making OFF the zero would
// silently withdraw Alt from any caller that had not yet learnt to set the bits.
//
// A phone reads LEFT and RIGHT the same way it reads BOTH: `UIKey.modifierFlags` carries one
// `.alternate` bit and no side, so a side-specific choice cannot be honoured, and reading it as OFF
// would take away the meta the reader asked for while reading it as BOTH costs only the accented
// character on the side they left free.
#define SLOPDESK_PHONE_KEY_OPTION_AS_ALT_MASK  (3u << 4)
#define SLOPDESK_PHONE_KEY_OPTION_AS_ALT_BOTH  (0u << 4)
#define SLOPDESK_PHONE_KEY_OPTION_AS_ALT_OFF   (1u << 4)
#define SLOPDESK_PHONE_KEY_OPTION_AS_ALT_LEFT  (2u << 4)
#define SLOPDESK_PHONE_KEY_OPTION_AS_ALT_RIGHT (3u << 4)
// The `named` a chord writes when its key is the printable scalar in `character` instead.
#define SLOPDESK_PHONE_KEY_NAMED_NONE ((uint8_t)0xFF)
// What capturing one press in the Settings chord recorder means — the SAME four answers, in the same
// order, that `slopdesk_key_capture_outcome` gives the Mac's recorder. Both write one override map.
#define SLOPDESK_PHONE_KEY_CAPTURE_CANCEL ((uint8_t)0)
#define SLOPDESK_PHONE_KEY_CAPTURE_CLEAR  ((uint8_t)1)
#define SLOPDESK_PHONE_KEY_CAPTURE_IGNORE ((uint8_t)2)
#define SLOPDESK_PHONE_KEY_CAPTURE_BIND   ((uint8_t)3)
// A key a MODE reads as a command rather than as input — Copy Mode and Hint Mode, the two places a
// pane answers keys instead of forwarding them. Six of the twenty-six special keys carry a meaning
// there; everything else, special or not, reaches the mode as its CHARACTER, which is what
// SLOPDESK_PHONE_MODAL_NONE says.
#define SLOPDESK_PHONE_MODAL_ESCAPE    ((uint8_t)0)
#define SLOPDESK_PHONE_MODAL_ENTER     ((uint8_t)1)
#define SLOPDESK_PHONE_MODAL_BACKSPACE ((uint8_t)2)
#define SLOPDESK_PHONE_MODAL_UP        ((uint8_t)3)
#define SLOPDESK_PHONE_MODAL_DOWN      ((uint8_t)4)
#define SLOPDESK_PHONE_MODAL_LEFT      ((uint8_t)5)
#define SLOPDESK_PHONE_MODAL_RIGHT     ((uint8_t)6)
#define SLOPDESK_PHONE_MODAL_NONE      ((uint8_t)0xFF)

// One `UIKey`: which key (`UIKey.keyCode`, a USB HID keyboard usage — the only signal that means the
// same thing under every layout and input method) and what that key produces under this layout
// (`base` = `charactersIgnoringModifiers`, which is what a ⌃ fold and a binding lookup are about).
// What the key COMMITTED is deliberately absent — for a special key it is noise, and for a printable
// one the proxy inserts it.
typedef struct {
    const uint8_t *base;
    size_t         base_len;
    uint16_t       hid_usage;  // 0 = none
    uint32_t       flags;      // SLOPDESK_PHONE_KEY_*
} SlopDeskPhoneKeyPress;

// Whether this press is encoded here rather than passed on to the text input path. A special key — every key
// with no printable output, Esc/Tab/Return/Delete and the whole nav and function block — or any of
// ⌃⌥⌘ is encoded; everything else is typing, ⇧ and a bare space included.
bool slopdesk_phone_key_routes_to_encoding(const SlopDeskPhoneKeyPress *press);
// The bytes this press sends, through `(out, cap)`. `0` means it sends nothing — bare typing, which
// is the proxy's, or a ⌘ combination, which is an app shortcut. No key this encoder resolves sends
// zero bytes, so the length is unambiguous. `application_cursor_keys` is the live DECCKM bit, which
// picks SS3 over CSI for the cursor block (the four arrows, Home and End) and nothing else.
size_t slopdesk_phone_key_encode(const SlopDeskPhoneKeyPress *press, bool application_cursor_keys,
                                 uint8_t *out, size_t cap);
// The chord this press makes, for the SAME user-overridable binding table the Mac's dispatcher
// reads. `named` is a `KeyChord.Key` case index or SLOPDESK_PHONE_KEY_NAMED_NONE, `character` the
// printable scalar in that case, `modifiers` bits 0-3. `false` leaves all three untouched: every
// field of a chord is a legitimate zero, so a length could not have said "not a chord".
bool slopdesk_phone_key_chord(const SlopDeskPhoneKeyPress *press, uint8_t *named,
                              uint32_t *character, uint8_t *modifiers);
// What this press does to the binding being RECORDED — one of SLOPDESK_PHONE_KEY_CAPTURE_*. Only a
// bind writes through, and it writes the chord exactly as `slopdesk_phone_key_chord` would. Stricter
// than that door in the two ways the Mac's recorder is stricter than its dispatcher: the space bar
// is no key here, and a base the chord grammar cannot spell back is refused rather than stored.
uint8_t slopdesk_phone_key_capture(const SlopDeskPhoneKeyPress *press, uint8_t *named,
                                   uint32_t *character, uint8_t *modifiers);
// The modal key one HID usage is — a SLOPDESK_PHONE_MODAL_* value. A USAGE rather than a whole
// press, because nothing about this answer reads the layout or the modifiers: `⌃v` in copy mode is
// the visual-block key, not an Escape, so the modes take the modifier state off the press
// themselves and ask this only "which key is it".
uint8_t slopdesk_phone_modal_key(uint16_t hid_usage);
// The accessory bar's armed ⌃ folding a soft-keyboard commit: the first scalar's control byte
// through `code`, the byte offset its remainder starts at through `rest`. `false` for empty text.
bool slopdesk_phone_key_fold_control(const uint8_t *text, size_t len, uint8_t *code, size_t *rest);

// The keyboard height at which the on-screen keyboard is the SOFTWARE one — a hardware keyboard
// leaves only a thin shortcut bar, and the ⌃/Esc/Tab/arrow row is only worth its space above this.
double slopdesk_phone_accessory_threshold(void);
bool slopdesk_phone_shows_accessory_bar(double keyboard_height, double threshold);

// The floating cursor: long-pressing the space bar and dragging, which on a phone with no hardware
// keyboard is the ONLY way to move the terminal cursor. `accumulated` is read AND written — the
// sub-threshold remainder is what makes a slow drag of many small deltas total correctly.
double slopdesk_phone_floating_cursor_threshold(void);
// The most bytes one feed can answer with — the arrow cap times the escape width, both of which are
// this side's to tune. A caller sizes its buffer at this rather than multiplying them out itself.
size_t slopdesk_phone_floating_cursor_run_capacity(void);
size_t slopdesk_phone_floating_cursor_feed(double *accumulated, double threshold, double delta_x,
                                           bool application_cursor_keys, uint8_t *out, size_t cap);

// The tiled tree, as its PRE-ORDER walk rather than as its persisted JSON. Both languages already
// agree on that JSON, and reusing it here would have been two lines — but `solve` runs on every
// layout pass, and a parse plus an allocation per frame is the kind of regression that vetoes a
// port. One array, one pass, no parse; the persisted codec stays what it is for, which is disk.
//
// Each node says how many DIRECT children follow it. A well-formed array is consumed exactly; a
// `child_count` that overruns, or a truncated tail, stops the walk and answers nothing rather than
// reading past the end — which matters here because a tree can arrive from a peer.
typedef struct {
    uint8_t        kind;  // 0 leaf · 1 split (anything else reads as a leaf)
    SlopDeskWsUuid id;    // a leaf's pane id, or a split's divider-group id
    uint8_t        axis;  // 0 horizontal (columns) · 1 vertical (rows)
    bool           weight_is_fixed;
    uint32_t       child_count;
    double         weight;  // this node's share WITHIN its parent; the root's is ignored
} SlopDeskWsTreeNode;

// One child's share, as the weights codec reads and writes it.
typedef struct {
    bool   is_fixed;
    double value;
} SlopDeskWsShare;

// The default floor on a solved leaf, as (width, height).
SlopDeskWsPoint slopdesk_ws_min_leaf(void);

// 0 = a tree the walk could not rebuild, which is the same answer an empty tree gives.
size_t slopdesk_ws_solve_layout(const SlopDeskWsTreeNode *nodes, size_t count,
                                SlopDeskWsRect rect, double min_width, double min_height,
                                SlopDeskWsFrame *out, size_t cap);
// One draggable seam. The rect is what is drawn and hit; everything after it is what a DRAG needs
// — the span it converts pixels against, the flex sum it converts them into, and the pair of
// weights it moves between. A `0` weight is a FIXED child, which is not draggable at all.
typedef struct {
    SlopDeskWsUuid split;
    uint32_t       child_index;  // the LEADING child: the seam is between it and the next
    uint8_t        axis;         // 0 horizontal (a column seam, dragged left/right) · 1 vertical
    SlopDeskWsRect rect;
    double         parent_span;  // a NESTED split's own length, so the drag tracks the cursor 1:1
    double         flex_sum;
    double         leading_weight;
    double         trailing_weight;
} SlopDeskWsDivider;

// The band a seam is drawn and hit with — wide enough to grab, so the drawn hairline can be thinner.
double slopdesk_ws_divider_thickness(void);
// Every seam of the tree, in pre-order. 0 = a tree the walk could not rebuild, which is the same
// answer a lone leaf gives: nothing to drag.
size_t slopdesk_ws_dividers(const SlopDeskWsTreeNode *nodes, size_t count, SlopDeskWsRect rect,
                            double thickness, SlopDeskWsDivider *out, size_t cap);
// The hover cursor's one-way-vs-two-way answer, from the same pixel floor the drag clamps at — so
// the arrow the person sees and the seam they get can never disagree.
bool   slopdesk_ws_divider_can_move(SlopDeskWsDivider handle, bool toward_leading);
// A live drag's proposed leading weight, clamped so BOTH panes keep that floor. Sum-preserving,
// and a pair too tight for two floors can only be dragged toward balance.
double slopdesk_ws_divider_clamped_weight(SlopDeskWsDivider handle, double proposed);
// One incremental pixel drag along the seam's axis, as the weight delta to offset from:
// `Δpixel / parent_span * flex_sum`, the inverse of a flex child's `extent = weight/flex_sum*span`.
// The span and the flex sum come out of the HANDLE, so one split's span can never be paired with
// another's partition — drop the flex-sum factor and a 50/50 seam trails the cursor at half speed.
// A handle without geometry answers 0, and the drag then sends nothing.
double slopdesk_ws_divider_weight_delta(SlopDeskWsDivider handle, double pixel_increment);
// The live drag's ratio readout, as whole percentages that sum to exactly 100. False is a
// degenerate pair — a fixed side reports weight 0 — and then neither out-param is touched: the cue
// is ABSENT rather than wrong. Both numbers cross, so no caller rounds the complement itself.
bool   slopdesk_ws_divider_percents(SlopDeskWsDivider handle, uint32_t *leading, uint32_t *trailing);

// MARK: The split tree's own operations
//
// Each of these ANSWERS a tree, written as the same pre-order walk they read. A count of SIZE_MAX
// means the op did not APPLY — a different answer from a tree of zero nodes, which would erase an
// arrangement the caller only meant to leave alone. Otherwise the §4 convention holds: the return is
// the node count needed, and nothing is written when it exceeds `cap`.

/// Where a pane sits relative to the nearest enclosing split on an axis.
typedef struct {
  SlopDeskWsUuid split;
  size_t child_index;
  size_t child_count;
} SlopDeskWsEnclosing;

size_t slopdesk_ws_tree_splitting(const SlopDeskWsTreeNode *nodes, size_t count,
                                  SlopDeskWsUuid target, uint8_t axis, SlopDeskWsUuid new_leaf,
                                  bool before, SlopDeskWsUuid fresh_split,
                                  SlopDeskWsTreeNode *out, size_t cap);
size_t slopdesk_ws_tree_inserting_beside(const SlopDeskWsTreeNode *nodes, size_t count,
                                         SlopDeskWsUuid leaf, SlopDeskWsUuid target, uint8_t axis,
                                         bool before, SlopDeskWsUuid fresh_split,
                                         SlopDeskWsTreeNode *out, size_t cap);
size_t slopdesk_ws_tree_inserting_at_root(const SlopDeskWsTreeNode *nodes, size_t count,
                                          SlopDeskWsUuid leaf, uint8_t axis, bool before,
                                          SlopDeskWsUuid fresh_split, SlopDeskWsTreeNode *out,
                                          size_t cap);
size_t slopdesk_ws_tree_removing(const SlopDeskWsTreeNode *nodes, size_t count,
                                 SlopDeskWsUuid target, SlopDeskWsTreeNode *out, size_t cap);
size_t slopdesk_ws_tree_resizing_divider(const SlopDeskWsTreeNode *nodes, size_t count,
                                         SlopDeskWsUuid split, size_t leading_index, double delta,
                                         SlopDeskWsTreeNode *out, size_t cap);
size_t slopdesk_ws_tree_evening_divider(const SlopDeskWsTreeNode *nodes, size_t count,
                                        SlopDeskWsUuid split, size_t leading_index,
                                        SlopDeskWsTreeNode *out, size_t cap);
size_t slopdesk_ws_tree_setting_divider_weight(const SlopDeskWsTreeNode *nodes, size_t count,
                                               SlopDeskWsUuid split, size_t leading_index,
                                               double leading_weight, SlopDeskWsTreeNode *out,
                                               size_t cap);
size_t slopdesk_ws_tree_swapping(const SlopDeskWsTreeNode *nodes, size_t count, SlopDeskWsUuid a,
                                 SlopDeskWsUuid b, SlopDeskWsTreeNode *out, size_t cap);
size_t slopdesk_ws_tree_rebalanced(const SlopDeskWsTreeNode *nodes, size_t count,
                                   SlopDeskWsTreeNode *out, size_t cap);
bool slopdesk_ws_tree_enclosing_split(const SlopDeskWsTreeNode *nodes, size_t count,
                                      SlopDeskWsUuid pane, uint8_t axis,
                                      SlopDeskWsEnclosing *answer);
bool slopdesk_ws_tree_first_leaf(const SlopDeskWsTreeNode *nodes, size_t count,
                                 SlopDeskWsUuid *answer);
bool slopdesk_ws_tree_structurally_equal(const SlopDeskWsTreeNode *left, size_t left_count,
                                         const SlopDeskWsTreeNode *right, size_t right_count);


// MARK: The re-tile layouts
//
// The leaf ORDER in, the tree out. `layout` is LayoutPreset's case index: evenHorizontal,
// evenVertical, mainVertical, mainHorizontal, tiled — and the main-* layouts take the FIRST leaf as
// the large one, so the caller decides what "active" means. `splits` is the identity pool the crate
// draws split ids from (it mints nothing of its own); `count + 1` entries is always enough. SIZE_MAX
// for fewer than two leaves, where a one-child split would violate the tree's arity rule.
size_t slopdesk_ws_retile(const SlopDeskWsUuid *leaves, size_t count, uint8_t layout,
                          const SlopDeskWsUuid *splits, size_t split_count,
                          SlopDeskWsTreeNode *out, size_t cap);


// MARK: The document's scalar field codec
//
// The leaves of the multiclient state protocol (docs/45). Every decoder is STRICT about width — a
// value of the wrong length answers false rather than a lenient prefix read — because these bytes
// came off a socket and a mis-numbered field must FAIL rather than succeed into something plausible.
//
// The out-parameter shape rather than a return value, because every one has to be able to say "these
// bytes are not a value of this kind" without a sentinel that could also be data: a lastExitCode of
// -1 is a real exit code, and 0xFFFFFFFF is its encoding.

// A one-byte field, and the same byte read as a BOOL. The bool reading is a door of its own
// rather than a `!= 0` composed by the caller: both of a bool's values are real answers, so the
// width refusal has to ride the return, and a side that read the byte as `== 1` instead would
// answer false for every non-canonical byte a peer sends without either side failing a decode.
bool slopdesk_ws_decode_bool(const uint8_t *bytes, size_t len, bool *out);
bool slopdesk_ws_decode_u8(const uint8_t *bytes, size_t len, uint8_t *out);
bool slopdesk_ws_decode_u8_pair(const uint8_t *bytes, size_t len, uint8_t *first, uint8_t *second);
bool slopdesk_ws_decode_u16_pair(const uint8_t *bytes, size_t len, uint16_t *first,
                                 uint16_t *second);
bool slopdesk_ws_decode_u32(const uint8_t *bytes, size_t len, uint32_t *out);
bool slopdesk_ws_decode_i32(const uint8_t *bytes, size_t len, int32_t *out);
bool slopdesk_ws_decode_i64(const uint8_t *bytes, size_t len, int64_t *out);
// SIZE_MAX when the count and the bytes disagree — a REFUSAL, not the empty list a well-formed zero
// count is.
size_t slopdesk_ws_decode_uuid_list(const uint8_t *bytes, size_t len, SlopDeskWsUuid *out,
                                    size_t cap);
size_t slopdesk_ws_encode_uuid_list(const SlopDeskWsUuid *ids, size_t count, uint8_t *out,
                                    size_t cap);
size_t slopdesk_ws_encode_string(const uint8_t *bytes, size_t len, size_t max_bytes,
                                 uint8_t *out, size_t cap);


// MARK: The snapshot and the diff
//
// The highest-risk parsing in the document: a count and a length, both chosen by whoever is on the
// other end of the socket. Every bound is checked against the bytes ACTUALLY remaining before any
// capacity is reserved, so a hostile 0xFFFFFFFF costs a comparison rather than four gigabytes.
//
// A decoded value is a SPAN into the caller's own input buffer, never a copy — the caller still
// holds the buffer, so the spans are live for exactly as long as they are useful.

size_t slopdesk_ws_max_entry_count(void);

/// One document entry: a key, and where its value sits in the buffer. `value.present` is false for a
/// DELETE, which is a key with no value.
typedef struct {
  uint8_t kind;
  uint8_t field;
  SlopDeskWsUuid object;
  SlopDeskWsSpan value;
} SlopDeskWsEntry;

// SIZE_MAX on malformed bytes — a REFUSAL, not the empty snapshot a well-formed zero count is.
size_t slopdesk_ws_decode_snapshot(const uint8_t *bytes, size_t len, SlopDeskWsEntry *out,
                                   size_t cap);
// Both counts are written even when a buffer was too small, so one call sizes both halves.
bool slopdesk_ws_decode_diff(const uint8_t *bytes, size_t len, SlopDeskWsEntry *sets_out,
                             size_t sets_cap, SlopDeskWsEntry *deletes_out, size_t deletes_cap,
                             size_t *sets_needed, size_t *deletes_needed);
size_t slopdesk_ws_encode_snapshot(const SlopDeskWsEntry *entries, size_t count,
                                   const uint8_t *blob, size_t blob_len, uint8_t *out, size_t cap);
size_t slopdesk_ws_encode_diff(const SlopDeskWsEntry *sets, size_t set_count,
                               const SlopDeskWsEntry *deletes, size_t delete_count,
                               const uint8_t *blob, size_t blob_len, uint8_t *out, size_t cap);


// MARK: The intent applier
//
// One client's requested topology change, decided here and nowhere else — the host runs it to
// decide what the document becomes and the client runs the SAME call for its optimistic overlay,
// so the two cannot disagree about what a split does.
//
// A topology is a split tree, which does not flatten into a struct without inventing a second
// grammar for it — and does not have to, because it already HAS one. The document goes in as the
// flat cells `slopdesk_ws_encode_snapshot` takes, and the result comes back as an encoded snapshot
// the caller reads with `slopdesk_ws_decode_snapshot`.

typedef struct {
    SlopDeskWsUuid id;
    SlopDeskWsSpan key;
} SlopDeskWsKeyedPane;

// The identity pool one intent can spend. Sized here rather than at the call site: a pool one short
// REPEATS an identity rather than failing, and two tabs sharing an id surfaces days later.
size_t slopdesk_ws_minted_ids_per_intent(void);

// The topology's two RING caps, by index: 0 the closed-tab ring, 1 the per-session focus MRU. An
// unknown index answers 0. These are REAPING thresholds the host applies, so a client holding a
// different number renders a ring whose tail the host already deleted, with no error anywhere.
size_t slopdesk_ws_topology_ring_cap(uint8_t index);

// Whether a (kind, field) pair is in the TOPOLOGY half — what a wholesale topology write REAPS by.
// A pane splits by FIELD: its `title` is topology and its `liveTitle` is not, one byte apart under
// the same object id. Two answers do not conflict, they silently delete or silently strand a cell.
bool slopdesk_ws_key_is_topology(uint8_t kind, uint8_t field);

// An intent argument cap the HOST validates against before it allocates: 0 a name's bytes,
// 1 a reorderTabs list, 2 a sub-payload blob. Unknown index answers 0, refusing everything.
size_t slopdesk_ws_intent_limit(uint8_t index);

// The wire size of one document key. Fixed, and the reason a truncated snapshot is rejected by
// arithmetic rather than by trial decoding.
size_t slopdesk_ws_key_encoded_size(void);

// One HALF of the pane field vocabulary: 0 the liveness fields, 1 the topology fields. §4-shaped.
// The two PARTITION the vocabulary — a field in neither is written and reaped by nobody, one in
// both makes a liveness recapture silently delete a persisted title.
size_t slopdesk_ws_pane_fields(uint8_t half, uint8_t *out, size_t cap);

// The `root` field numbers a topology write must NOT reap — reserved for config that does not
// cross (docs/45 §5.3). §4-shaped, so a caller sizes from the answer.
size_t slopdesk_ws_reserved_root_fields(uint8_t *out, size_t cap);

// The status byte for one outcome, by arm order: applied, stale, invalid, not-found, unknown-op.
// Exported because the numbering is the WIRE's and therefore golden-pinned — a caller that wrote it
// down beside this would be a second copy of a frozen number.
uint8_t slopdesk_ws_intent_status(uint8_t index);

// `project_keys` span the SAME `blob` the entries do. `status` receives the intent-status byte on
// every path including the refusals, so a caller that only wants the verdict passes a null `out`.
// A refusal answers 0 bytes — not the four an empty snapshot encodes to.
size_t slopdesk_ws_apply_intent(uint8_t op, const uint8_t *args, size_t args_len,
                                const SlopDeskWsEntry *entries, size_t entry_count,
                                const SlopDeskWsKeyedPane *project_keys, size_t project_key_count,
                                const uint8_t *blob, size_t blob_len,
                                const SlopDeskWsUuid *minted, size_t minted_count, bool pristine,
                                uint8_t *status, uint8_t *out, size_t cap);


// MARK: The pane's LIVENESS half — what is true about its process, and what happens when it stops
//
// The other side of the line `slopdesk_ws_key_is_topology` draws. Topology is what the person
// ARRANGED and survives a restart; liveness is derived from a running process, republished after
// every restart and never persisted. Three decisions live here and none of them FAILS when it is
// answered twice — they render, which is why they are asked:
//
//   * a merge is CLEAR-then-write, so a fact that stopped being true disappears rather than
//     latching (the finished command, the agent that exited);
//   * marking a pane dead keeps exactly the two fields that describe a PLACE — its directory and
//     the project that directory belongs to — and drops every claim about a process;
//   * the reconciler's reap is THREE-way, and its two-way ancestor deleted the person's layout on
//     every host restart, since a just-restarted host has a full layout and no processes at all.
//
// The document rides its own encoding, as the intent applier's and the state file's do: cells in as
// the flat `SlopDeskWsEntry` pairs `slopdesk_ws_encode_snapshot` takes, the result back as an
// encoded snapshot read with `slopdesk_ws_decode_snapshot`. A liveness RECORD is the one thing on
// this path with no encoding of its own to borrow — it is what the host builds from a live PTY
// session before any of it has reached a cell — so it crosses as the struct below, its seven
// strings SPANS into the same blob the entries span. Every optional non-string carries a presence
// flag beside it rather than reserving a value to mean absent: a 0×0 grid and a pane whose size was
// never observed are different states, and `liveTitle` absent (never asserted) versus present and
// empty (RETIRED by the agent that owned it) is the same distinction one step sharper.

typedef struct {
    SlopDeskWsUuid id;
    SlopDeskWsSpan live_title;
    SlopDeskWsSpan cwd;
    SlopDeskWsSpan project_key;
    SlopDeskWsSpan foreground_process;
    SlopDeskWsSpan running_command;
    SlopDeskWsSpan agent_label;
    SlopDeskWsSpan agent_intent;
    int64_t  last_activity_ms;   // 0 = never observed; it needs no flag, the field says so itself
    uint32_t completion_epoch;
    uint32_t last_duration_ms;   // read only when has_last_duration_ms
    int32_t  last_exit_code;     // read only when has_last_exit_code
    uint16_t grid_cols;          // read only when has_grid
    uint16_t grid_rows;          // read only when has_grid
    uint8_t  liveness;           // always meaningful: its presence IS the pane's existence
    uint8_t  agent_state;        // read only when has_agent
    uint8_t  agent_kind;         // read only when has_agent
    uint8_t  progress_state;     // read only when has_progress
    uint8_t  progress_percent;   // read only when has_progress
    bool     title_fresh;
    bool     command_running;
    bool     has_agent;
    bool     has_progress;
    bool     has_last_exit_code;
    bool     has_last_duration_ms;
    bool     has_grid;
} SlopDeskWsPaneLiveness;

// One record's cells, as an encoded snapshot. The PROJECTION rule, not a serialization: a field is
// emitted only when it carries a non-default value, with exactly one exception — the liveness state
// is always emitted, so a pane's presence in the document is never ambiguous. Never 0 for a record
// that is there, since the existence marker alone is a cell; `0` is the null record.
size_t slopdesk_ws_pane_liveness_entries(const SlopDeskWsPaneLiveness *record,
                                         const uint8_t *blob, size_t blob_len,
                                         uint8_t *out, size_t cap);

// One pane's record read back OUT of a document's cells. Every field decodes independently and a
// malformed one falls back to its default rather than failing the record: these bytes came off a
// socket, and one bad grid must not blank a pane's title.
//
// `found` is written on EVERY path, including the one where the answer did not fit, so a caller
// sizing with `(NULL, 0)` learns from the same call whether there is a pane here at all. The return
// is how many bytes of STRINGS the answer needs, §4-shaped, and `record`'s spans index `out` — so
// both are written together or neither is. A found record with no strings answers 0, which is why
// the existence question is `found` and not the return.
size_t slopdesk_ws_pane_liveness_read(const SlopDeskWsEntry *entries, size_t count,
                                      const uint8_t *blob, size_t blob_len,
                                      const SlopDeskWsUuid *pane, bool *found,
                                      SlopDeskWsPaneLiveness *record, uint8_t *out, size_t cap);

// Replaces the liveness half of every named pane, leaving their topology fields untouched. Panes
// the document holds but `records` does not name are LEFT ALONE — reaping is the next door down.
// That is why these are two entry points and not one with a flag: the wrong value of the flag is
// the whole workspace of a host that restarted and has captured nothing yet.
//
// `records` span the SAME `blob` the entries do. `changed` is written on every path and is what a
// caller versions by — every bump costs every subscriber a frame, so a no-op recapture must not
// move a version number.
//
// A document that did NOT move answers 0 and is not encoded at all. Read `changed` first: there is
// no new document to hand back, and the caller was going to discard the bytes. The three folding
// doors here (merge, mark-dead, reconcile) all share that contract, and it is what makes the idle
// backstop cheap — a settled reconcile of a 24-pane workspace measures ~69 us against ~84 us for
// one that moved, on an M-series host.
size_t slopdesk_ws_merge_pane_liveness(const SlopDeskWsEntry *entries, size_t count,
                                       const SlopDeskWsPaneLiveness *records, size_t record_count,
                                       const uint8_t *blob, size_t blob_len,
                                       bool *changed, uint8_t *out, size_t cap);

// Declares that one pane has no process — the detached store's TTL eviction. A pane the document
// has never heard of is MINTED as a dead one rather than ignored, because the existence marker is
// always written: absent is what the reaper below reads as "nothing owns this" one tick later.
size_t slopdesk_ws_mark_pane_dead(const SlopDeskWsEntry *entries, size_t count,
                                  const uint8_t *blob, size_t blob_len,
                                  const SlopDeskWsUuid *pane, bool *changed,
                                  uint8_t *out, size_t cap);

// One reconciler pass, the three-way rule: captured panes take what the capture said, panes the
// topology still names but nothing captured go STALE rather than being deleted, and panes in
// neither are reaped whole because nothing owns them. A captured pane the topology has never heard
// of is NOT reaped — a pane spawned between the last topology write and this tick would otherwise
// be deleted by the tick that first saw it. Same `blob` and same `changed` contract as the merge;
// this one runs on a 500 ms backstop, so an idle host reconciling to the same answer costs nothing.
size_t slopdesk_ws_reconcile_panes(const SlopDeskWsEntry *entries, size_t count,
                                   const SlopDeskWsPaneLiveness *records, size_t record_count,
                                   const uint8_t *blob, size_t blob_len,
                                   bool *changed, uint8_t *out, size_t cap);


// MARK: The repair pass a loader runs
//
// A hand-edited or partially-written workspace must come back rather than be refused, so every
// degenerate shape has a defined repair: an orphan spec is dropped, a spec-less pane is re-seeded,
// an out-of-range selection is clamped, an empty workspace is minted from scratch, and a persisted
// video pane is dropped rather than re-docked because a remote desktop never restores.
//
// This ran in BOTH languages until 2026-08-20 and the two did not shadow each other — the Swift
// copy fired on file load, this one on every intent — so launch-time and gesture-time repair
// reached different trees for the same input (docs/55 §8).
//
// It rides the document's own bytes, as the intent applier does: the cells go in as the flat
// `SlopDeskWsEntry` pairs `slopdesk_ws_encode_snapshot` takes, and the repaired tree comes back as
// an encoded snapshot read with `slopdesk_ws_decode_snapshot`. One shape cannot make that trip: a
// session with NO usable tab is dropped by the document ingest on both sides, rightly, since a host
// push naming one describes nothing — so the caller repairs that single case before encoding, and
// `check-supervisor.sh` pins it to stay that one case.

// The identity pool one repair can spend over a workspace of that shape. Sized here rather than at
// the call site: a pool one short REPEATS an identity rather than failing, and two tabs born with
// one id surfaces days later as a tab that will not close.
size_t slopdesk_ws_normalize_minted_ids(size_t sessions, size_t detached);

// How many repair passes there are, so a caller can neither name one this build lacks nor miss one
// it grew.
size_t slopdesk_ws_normalize_pass_count(void);

// `pass` is the arm order: 0 the spec table, 1 the selections, 2 both in the order a load applies
// them (specs first, so the selection repair sees a consistent set of panes), 3 the whole launch
// restore — video panes dropped, detached panes re-docked, the persisted selection preserved.
// A byte naming no pass answers 0, which is the ONLY 0: every pass over every document answers a
// workspace, because a document with none in it is answered with the re-seeded default.
size_t slopdesk_ws_normalize(uint8_t pass, const SlopDeskWsEntry *entries, size_t entry_count,
                             const uint8_t *blob, size_t blob_len,
                             const SlopDeskWsUuid *minted, size_t minted_count,
                             uint8_t *out, size_t cap);

// Whether a `pane/kind` byte names a VIDEO pane — the predicate the launch restore DROPS by. A
// second spelling of it is the exact drift docs/55 §8 records: `kind == .desktop` and
// `PaneKind::is_video` select the same panes today and stop agreeing the day a third video-ish kind
// lands on one side only. An unknown byte reads as a terminal, so it is a degraded pane rather than
// a stream opened for a window that will never exist.
bool slopdesk_ws_pane_kind_is_video(uint8_t kind);

// How many pane kinds there are, so a caller can WALK the vocabulary rather than name its members.
size_t slopdesk_ws_pane_kind_count(void);

// Whether a `pane/kind` byte names a pane text can be TYPED into — the recipient set for broadcast,
// or synchronized, input. It is the other half of the classification the video predicate above
// makes, and it is a door for that predicate's reason one register up: asking for one of a pair and
// transcribing the other is the shape docs/55 §8 catalogues, and it had already happened here — the
// Swift side spelled `self == .terminal` beside a `PaneKind::can_receive_text` in the crate that no
// Rust caller had ever reached. A third kind that both streams a display and takes typed text would
// have split the broadcast recipient set from the restore filter with both suites green.
//
// An unknown byte reads as a terminal and so DOES take text. Failing OPEN, the way the video
// predicate does: a broadcast line delivered to a pane that renders it is a better worst case than a
// keystroke silently dropped for the pane the person is looking at.
bool slopdesk_ws_pane_kind_can_receive_text(uint8_t kind);

// Which pane kind a persisted DISCRIMINATOR names. The workspace FILE's string form is read on the
// Rust side of its own door; the one file whose decoder is still Foundation's is `device-prefs.json`,
// whose captured session templates carry a `PaneKind` per leaf. The five retired names — claudeCode,
// web, chooser, remoteGUI, systemDialog — fold to `terminal` here rather than being spelled a second
// time in Swift: `DevicePreferences` decodes as one synthesized whole, so a kind that THROWS resets
// the template library, the latched video modes and the per-host connection targets together, and
// nothing logs it.
//
// `-1` is "a name this build has never had" — corruption rather than age. It is signed for the reason
// `slopdesk_fuzzy_rank` is: 0 is the most common REAL answer (it is `terminal`, which is what every
// folded retired name becomes), so `size_t` has no room for a refusal. Bytes that are not valid UTF-8
// refuse too; a discriminator is one of a closed set of ASCII names.
int32_t slopdesk_ws_pane_kind_from_raw(const uint8_t *raw, size_t len);

// The title a re-seeded pane takes, and the name a fresh workspace's first session takes. §4-shaped
// and asked for rather than transcribed: a caller comparing against its own copy passes on a
// default this crate stopped producing, and the fresh-workspace shape test IS that comparison.
size_t slopdesk_ws_default_pane_title(uint8_t *out, size_t cap);
size_t slopdesk_ws_default_session_name(uint8_t *out, size_t cap);
size_t slopdesk_ws_default_desktop_pane_title(uint8_t *out, size_t cap);


// MARK: The things that SPAWN panes — a template's layout, and the shipped tables
//
// These are the one family here whose Swift original could NOT be deleted in the same change.
// `SessionTemplate` is `Codable` and is the currency of the device-preferences file, so its Swift
// decoder is how a person's saved layouts actually come back; deleting it would delete the store's
// ability to read its own file. docs/55 §7 step 6 names that case and says what is owed instead —
// PIN it: same inputs to both sides, assert the same output. These doors exist so
// `SessionTemplateRepairDifferentialTests` can, and they are the whole reason
// `slopdesk_workspace::templates` stopped being thirteen unit tests with no caller.
//
// A layout crosses as a PRE-ORDER byte stream, the shape `slopdesk_ws_solve_layout` already uses
// for the split tree — a tag, its payload, then its children. The encoding, written down once:
//
//   text     := u32 BE length, then that many UTF-8 bytes
//   opt-text := u8 present (0 or 1), then text when present
//   uuid     := 16 bytes, canonical UUID order
//   node     := 0x00 u8:kind text:title opt-text:cwd opt-text:command      -- a pane
//             | 0x01 u8:axis u32:child_count  node × child_count           -- a split, visual order
//   template := uuid:id text:name text:symbol u8:is_built_in node:layout
//   preset   := uuid:id text:name text:command opt-text:working_directory
//               u8:has_split [u8:axis text:secondary_command when has_split]
//               text:symbol u8:is_built_in
//   table    := u32 BE count, then that many records
//
// The lengths are u32 rather than the wire's u16 because `put_length_prefixed_str` CLAMPS at 64 KiB,
// and a differential that agrees because both sides truncated the same title is worse than none.
// A present empty string and an absent one are different answers, §4b's presence rule per field.
//
// The walk is the contract: nothing is seekable, the reader goes forward once, and a stream it
// cannot consume EXACTLY — truncated, with a trailing byte, with a tag or presence byte that is
// neither of its two values — answers 0. That refusal is a shape disagreement between two encoders,
// never a degenerate template: a degenerate template has a defined repair and always answers one.

// The repair a persisted layout runs: a childless split becomes a plain terminal, a one-child split
// collapses into its child, and anything nested past `slopdesk_ws_max_depth` collapses to its first
// pane. Repaired, never rejected — the input is a file a person can edit. `0` is the stream refusal
// above and nothing else; the shortest layout there is encodes to seven bytes.
size_t slopdesk_ws_template_repair(const uint8_t *layout, size_t len, uint8_t *out, size_t cap);

// The tables a fresh workspace ships with. They cross because a shipped row's IDENTITY is fixed
// rather than minted — so that a re-seed or a settings reset MATCHES the existing row instead of
// appending a second copy of it — which makes each table a set of constants written in two
// languages, where a drift of one byte in sixteen surfaces as a duplicated menu row weeks later
// with nothing in any log.
size_t slopdesk_ws_built_in_templates(uint8_t *out, size_t cap);
size_t slopdesk_ws_built_in_launch_presets(uint8_t *out, size_t cap);


// MARK: The workspace state FILE
//
// What of the document survives a host restart, and in what shape on disk. The JSON is the boring
// half; the FILTER is not. Persisting the entry map wholesale would restore `commandRunning = 1`,
// `agentState = working` and a liveness of `attached` for a pane whose child exited weeks ago —
// a workspace of fake-live rows, busy dots spinning for nothing — so a second answer to "may this
// cell touch the disk" does not conflict with the first, it RENDERS.
//
// Both directions ride the document's own encoding, as the intent applier's do: the cells go in as
// the flat `SlopDeskWsEntry` pairs `slopdesk_ws_encode_snapshot` takes, and a decoded file comes
// back as an encoded snapshot read with `slopdesk_ws_decode_snapshot`.

// Whether one cell survives a restart. A KIND and a FIELD are all the rule reads — a pane splits by
// field, its `title` surviving where its `liveness` must not — so the caller's filter loop is a
// loop and not a decision. A kind this build does not know answers false: bytes nothing can read
// and nothing can reap would leave ghost objects with nothing able to remove them.
bool slopdesk_ws_state_file_is_persisted(uint8_t kind, uint8_t field);

// The file's bytes for a document, §4-shaped. UTF-8 JSON, sorted keys, canonical entry order, so
// two saves of one value are byte-identical. The cells are taken as given — what belongs on disk is
// the caller's own pass through `slopdesk_ws_state_file_is_persisted`. Encoding cannot fail.
size_t slopdesk_ws_state_file_encode(const SlopDeskWsEntry *entries, size_t count,
                                     const uint8_t *blob, size_t blob_len,
                                     uint8_t *out, size_t cap);

// Reads a file back, answering the surviving cells as an encoded SNAPSHOT. `status` receives the
// refusal byte on EVERY path — index 0 of `slopdesk_ws_state_file_status` when the load worked — so
// a caller wanting only the verdict passes a null `out`. `version` receives the version the file
// CLAIMED and is written on the version-mismatch path ONLY: every int64 is a version a hand edit
// can type, so none of them could have meant "not about a version". A refusal answers 0 bytes,
// which is not the four an empty document encodes to.
size_t slopdesk_ws_state_file_decode(const uint8_t *bytes, size_t len, uint8_t *status,
                                     int64_t *version, uint8_t *out, size_t cap);

// The refusal byte for one outcome, by index: 0 the load that worked, then the arms — 1 malformed
// (not our file), 2 version mismatch (our file, another shape of the store), 3 malformed row. An
// index past the last answers the malformed byte, which refuses rather than admits. Exported
// because a transcribed copy that drifted on one arm would turn a corrupt row into a
// mint-the-default, and the old file would not be kept aside.
uint8_t slopdesk_ws_state_file_status(uint8_t index);

// ---- The document's canonical order ----
//
// The wire's emission order is ascending kind, then the object id's BYTES, then field — and on the
// far side it is not a sort at all: the document is a `BTreeMap` whose key order IS that order, so
// nothing there can drift from the encoder. A caller whose document is an unordered map has to
// DERIVE it, and deriving it a second time is the pair docs/55 §8 catalogues in its nastiest form:
// two orders never disagree loudly, they RE-EMIT. A snapshot stops being byte-deterministic and a
// diff churns on map iteration order, which reads downstream exactly like a real change.
//
// The answer is a PERMUTATION, not the sorted keys: the caller already holds them and is asking
// where they GO, so handing eighteen bytes per cell back to say what an index says would copy a
// whole snapshot's keys for nothing.

typedef struct {
    uint8_t        kind;
    uint8_t        field;
    SlopDeskWsUuid object;
} SlopDeskWsDocKey;

// `out[i]` is the index, into `keys`, of the key that places `i`-th. Returns how many places there
// ARE, which is always `count` — every key comes back exactly once, so a caller rebuilds its array
// from the answer without checking for a hole. A short `cap` leaves `out` untouched and reports the
// same number, which is the §4 retry at a size the caller derives rather than guesses.
size_t slopdesk_ws_key_order(const SlopDeskWsDocKey *keys, size_t count, uint32_t *out, size_t cap);


// MARK: The client's workspace FILE
//
// The other file: the CLIENT's `workspace.json`, the arrangement a launch restores. Its decoder is
// a repairing one because the file is a person's to edit and a half-typed one still has to open,
// and the repairs are the reason it had to stop being written twice. Swift's decoder named an
// id-less split `?? SplitNodeID()` — a fresh uuid every load — where the Rust one DERIVES the name
// from the divider's place in the tree, so a `splitNode/<id>/weight` cell written before a relaunch
// was orphaned after it and every divider a person had dragged snapped back with nothing logged.
// docs/55 §8's `derived_split_id` row is what this closes.
//
// Both directions ride the document's own encoding, as the state file's and the intent applier's
// do: cells in as the flat `SlopDeskWsEntry` pairs `slopdesk_ws_encode_snapshot` takes, a decoded
// file back as an encoded snapshot read with `slopdesk_ws_decode_snapshot`. The decode REPAIRS
// before it answers, which is forced rather than chosen — a session with no tab and a leaf with no
// spec are both spellable in the file and neither is spellable in a cell, so the shape the crossing
// cannot carry never reaches it.

// The identities a decode of THESE bytes can spend, asked of the file because the shape is what the
// caller does not know yet. Sized here for the reason every pool here is: one short repeats an
// identity, and two panes sharing one is a pane that reattaches to a process it never opened.
size_t slopdesk_ws_workspace_file_minted_ids(const uint8_t *bytes, size_t len);

// The file's bytes for a workspace, §4-shaped. UTF-8 JSON, sorted keys, trailing newline, so two
// saves of one arrangement are byte-identical. Only the topology half of the cells is read — the
// file is a LAYOUT, and liveness has no business on a disk that outlives the process it describes.
// Encoding cannot fail, so there is no status; a document with no workspace in it writes an empty
// one rather than nothing, because the file has to be a file.
//
// `schema_version` travels BESIDE the cells because the document has no cell for it: it is a
// property of this FILE and not of the shape, and the topology names it as a deliberate omission.
// The value written is the CALLER's, never this build's — a door that defaulted it would make every
// file the app saved claim the version the app reads, and the decode's version-mismatch arm would be
// reachable only from a file somebody hand-edited.
size_t slopdesk_ws_workspace_file_encode(const SlopDeskWsEntry *entries, size_t count,
                                         const uint8_t *blob, size_t blob_len,
                                         int64_t schema_version,
                                         uint8_t *out, size_t cap);

// Reads a file back, answering the REPAIRED workspace as an encoded snapshot. `minted` is the pool
// `slopdesk_ws_workspace_file_minted_ids` sized over these same bytes — panes are minted from it,
// dividers are derived inside and cost nothing. `status` receives the refusal byte on EVERY path —
// index 0 of `slopdesk_ws_workspace_file_status` when the load worked — so a caller wanting only
// the verdict passes a null `out`. `version` receives the version the file CLAIMED and is written
// on the version-mismatch path ONLY. A refusal answers 0 bytes and nothing else does: the repair
// re-seeds a workspace that named nothing, so a load past the refusal always has a session to say.
size_t slopdesk_ws_workspace_file_decode(const uint8_t *bytes, size_t len,
                                         const SlopDeskWsUuid *minted, size_t minted_count,
                                         uint8_t *status, int64_t *version,
                                         uint8_t *out, size_t cap);

// The refusal byte for one outcome, by index: 0 the load that worked, then the arms — 1 malformed
// (not a workspace file), 2 version mismatch (a workspace file of another shape), 3 more panes than
// a launch can hold. An index past the last answers the malformed byte, which refuses rather than
// admits. Exported because a transcribed copy that drifted on one arm would write over the file a
// person's whole arrangement is in instead of keeping it aside.
uint8_t slopdesk_ws_workspace_file_status(uint8_t index);

// How many panes one file may name before the decode refuses it with status index 3. Asked for
// rather than spelled twice, like every other in-process cap here — and this one is a REFUSAL
// threshold, so a drifted second copy does not read as a disagreement: the near side would build a
// file it believes fits, the far side would refuse it, and the user would meet a workspace reset to
// the default with nothing anywhere saying why.
size_t slopdesk_ws_workspace_file_max_panes(void);


// MARK: The layout structure and the split weights
//
// The layout decoder is ITERATIVE where a recursive one would need a depth cap to stay safe: it
// walks a flat array with an explicit frame stack, so a hostile nesting depth cannot overflow a
// stack that is never used. SIZE_MAX when the bytes do not decode — an unknown tag, a truncated
// node, a split claiming more children than it carries, trailing bytes, or a tree past the depth
// cap. `depth_exceeded` says which: only the last of those sets it, because a too-deep tree is a
// well-formed document this build declines to hold where the rest are a bug or an attack.

/// One node of the layout structure, in a pre-order walk.
typedef struct {
  uint8_t kind;
  uint8_t axis;
  uint8_t child_count;
  SlopDeskWsUuid id;
} SlopDeskWsLayoutNode;

size_t slopdesk_ws_decode_layout(const uint8_t *bytes, size_t len, SlopDeskWsLayoutNode *out,
                                 size_t cap, bool *depth_exceeded);
size_t slopdesk_ws_encode_layout(const SlopDeskWsLayoutNode *walk, size_t count, uint8_t *out,
                                 size_t cap);
size_t slopdesk_ws_decode_weights(const uint8_t *bytes, size_t len, SlopDeskWsShare *out,
                                  size_t cap);
size_t slopdesk_ws_encode_weights(const SlopDeskWsShare *shares, size_t count, uint8_t *out,
                                  size_t cap);

// The fixed-width ENCODERS, and the one decoder the key layer still needed. These carry no retry:
// the answer's width is known before the call, so a caller sizes its buffer once.
bool slopdesk_ws_decode_uuid(const uint8_t *bytes, size_t len, SlopDeskWsUuid *out);
size_t slopdesk_ws_encode_key(uint8_t kind, SlopDeskWsUuid object, uint8_t field_tag, uint8_t *out,
                              size_t cap);
size_t slopdesk_ws_encode_u32(uint32_t value, uint8_t *out, size_t cap);
// pane/lastExitCode, four bytes big-endian carrying the u32 bit pattern — so a signal-killed
// child's negative code survives with no sign convention for either end to get wrong. Beside the
// unsigned door rather than composed from it: the bit pattern IS the convention, and the decode
// half of that round trip was already being chosen on this side of the boundary.
size_t slopdesk_ws_encode_i32(int32_t value, uint8_t *out, size_t cap);
size_t slopdesk_ws_encode_i64(int64_t value, uint8_t *out, size_t cap);

// MARK: - The two composite field values (docs/55 §6)
//
// `session/detachedPanes` and `pane/videoTarget` are the last two field values that were parsed in
// Swift. Both came off a socket, so both are decoded by `rust/slopdesk-workspace`'s `state_codec`
// under the same rule as every other field: a count or a length that disagrees with the bytes is a
// DROP, never a lenient prefix read.
//
// Absence is a flag in both. The wire spells "no origin tab" as the all-zero uuid because the pair
// is fixed-width, and it spells "not on a display" as a presence byte because display 0 is the main
// display — neither sentinel survives the crossing.

/// A detached pane and the tab it came from, if that is still known.
typedef struct {
  SlopDeskWsUuid pane;
  SlopDeskWsUuid origin;
  bool has_origin;
} SlopDeskWsDetachedPane;

/// A pane's video source. `title` and `app_name` span the bytes the CALLER lent to the decode, so
/// they are meaningful only while that buffer is alive.
typedef struct {
  uint32_t window_id;
  uint32_t display_id;
  bool has_display;
  SlopDeskWsSpan title;
  SlopDeskWsSpan app_name;
} SlopDeskWsVideoTarget;

size_t slopdesk_ws_decode_detached_panes(const uint8_t *bytes, size_t len,
                                         SlopDeskWsDetachedPane *out, size_t cap);
size_t slopdesk_ws_encode_detached_panes(const SlopDeskWsDetachedPane *panes, size_t count,
                                         uint8_t *out, size_t cap);
bool slopdesk_ws_decode_video_target(const uint8_t *bytes, size_t len, SlopDeskWsVideoTarget *out);
size_t slopdesk_ws_encode_video_target(uint32_t window_id, uint32_t display_id, bool has_display,
                                       const uint8_t *blob, size_t blob_len, SlopDeskWsSpan title,
                                       SlopDeskWsSpan app_name, uint8_t *out, size_t cap);

/* ---------------------------------------------------------------------------- *
 * The video path's forward error correction.
 *
 * A frame's fragments are a LIST, not a span, so they cross as one: a blob list is
 *
 *     u32 count | for each: u32 len | len bytes        (big-endian)
 *
 * where len == 0xFFFFFFFF marks a fragment that was lost in flight and carries no bytes. A
 * present-but-EMPTY fragment writes len == 0, which is a different thing: repairing one that was
 * never lost would corrupt the frame. Both calls answer with a blob list under §4's convention, so
 * a refusal is 0 and an empty answer is the four bytes of an empty list.
 *
 * The two answers do NOT mean the same thing. `parity` answers with the parity shards, all present.
 * `recover` answers with the REPAIRS: a list as long as the data list in which a fragment is
 * present only if this call is the reason it exists, so everything that arrived intact — and every
 * hole the code could not close — comes back absent. A single-loss frame is therefore one shard and
 * a run of four-byte absences, not a copy of the whole frame the caller just passed in. Arguments
 * are copied rather than described for a reason worth reading before changing it: docs/55 §4d.
 * ---------------------------------------------------------------------------- */

size_t slopdesk_video_fec_parity(size_t k, size_t m, size_t group_size, const uint8_t *data,
                                 size_t data_len, uint8_t *out, size_t cap);
size_t slopdesk_video_fec_recover(size_t k, size_t m, size_t group_size, const uint8_t *data,
                                  size_t data_len, const uint8_t *parity, size_t parity_len,
                                  uint8_t *out, size_t cap);

/* ---------------------------------------------------------------------------- *
 * The recovery channel: what the client says when it loses a frame, and when it stops asking.
 *
 * The message crosses FLAT, not as a tagged union. Six arms, one of them variable-length; a C union
 * would have to be kept in step with the Rust enum by hand on BOTH sides, which is the drift this
 * port removes. So every arm's fields sit beside each other with a type byte over them, and reading
 * a field an arm does not carry is a caller error the type byte already names.
 *
 * The NACK indices need no second call: the codec caps them at slopdesk_recovery_constant(1), so a
 * buffer that size can never be told to ask again. They land during the one decode and frag_count
 * says how many are real. A NULL frags buffer still parses and still counts.
 *
 * `decode` answers TRUNCATED or MALFORMED, writing nothing, for a short body or for an unknown
 * type, a NACK over the cap or TRAILING bytes. The two are told apart because the caller's own
 * vocabulary tells them apart; the malformed REASON does not cross, being diagnostic only. The
 * trailing-bytes rejection is load-bearing rather than fastidious: the
 * host's request deduper keys on the RAW datagram bytes, so a decoder tolerating suffixes would let
 * suffix-varied copies of one logical request each decode identically and each bypass the dedup,
 * firing a second refresh or IDR. `encode` returns 0 for a type byte no arm answers to.
 *
 * The loss window crosses as a PLAIN ARRAY, because a ring of timestamps is data. The caller keeps
 * the array and this side keeps the law: `note` answers the ring that pruning and the capacity drop
 * leave behind, `observing` reads one without touching it. Nothing is owned across the boundary and
 * no shape has to be mirrored here.
 *
 * `constant(index)`: 0 the no-frame-decoded sentinel · 1 the NACK fragment cap · 2 the redundancy
 * copy cap.
 * ---------------------------------------------------------------------------- */

typedef struct {
  uint32_t stream_seq;
  uint32_t from_frame_id;
  uint32_t to_frame_id;
  uint32_t last_decoded_frame_id;
  uint32_t frame_id;
  uint32_t frames_received;
  uint32_t fec_recovered;
  uint32_t unrecovered;
  uint32_t latest_host_send_ts;
  uint32_t client_hold_ms;
  uint32_t owd_jitter_micros;
  uint32_t owd_trend_milli;
  uint32_t owd_trend_flags;
  uint32_t pacer_late_frames;
  uint32_t pacer_present_gaps;
  uint32_t pacer_depth;
  uint16_t frag_count;
  uint16_t shape_id;
  uint8_t message_type;
} SlopDeskRecoveryMessage;

uint32_t slopdesk_recovery_constant(uint8_t index);
size_t slopdesk_recovery_encode(const SlopDeskRecoveryMessage *message, const uint16_t *frags,
                                uint8_t *out, size_t cap);
#define SLOPDESK_RECOVERY_DECODE_OK 0u
#define SLOPDESK_RECOVERY_DECODE_TRUNCATED 1u
#define SLOPDESK_RECOVERY_DECODE_MALFORMED 2u

uint32_t slopdesk_recovery_decode(const uint8_t *bytes, size_t len, SlopDeskRecoveryMessage *out,
                                  uint16_t *frags, size_t frags_cap);
double slopdesk_recovery_escalation_floor_seconds(const uint8_t *raw, size_t len);
bool slopdesk_recovery_should_escalate_to_idr(double idr_timeout_rtt_multiple,
                                              double lossy_idr_timeout_rtt_multiple,
                                              double lossy_escalation_floor,
                                              double lossy_escalation_floor_rtt_multiple,
                                              double elapsed_since_request, double rtt,
                                              bool observing_loss);
size_t slopdesk_recovery_send_offsets(size_t copies, double spacing, double *out, size_t cap);
size_t slopdesk_recovery_clamped_copies(size_t copies);
double slopdesk_recovery_all_copies_lost_probability(double per_datagram_loss, size_t copies);
double slopdesk_recovery_expected_request_loss_freeze(double per_datagram_loss, size_t copies,
                                                      double escalation_delay);
/* The host frameQueue timer's decision: re-encode the cached buffer as a forced keyframe?
 *
 * The decider's whole state is the first four doubles, so it crosses as scalars rather than as a
 * handle — there is nothing to own across the call. `0.0` is the "never happened" sentinel for both
 * anchors, and it is NOT a time: an anchor of zero means no such encode has occurred, never one at
 * time zero.
 *
 * `quiet_window` defaults to `heartbeat` on the Rust side; a caller with no separate window passes
 * `heartbeat` twice. */
bool slopdesk_static_idr_should_reencode(double heartbeat, double quiet_window,
                                         double last_complete_encode, double last_synthetic_encode,
                                         double now, bool forced_latched, bool has_retained_buffer);
/* Rewrites the ring IN PLACE: `events` is both the `count` timestamps held and the `cap` slots the
 * answer may use. Returns the new length; `cap` too small leaves the buffer untouched. */
size_t slopdesk_recovery_loss_window_note(double window_seconds, size_t capacity, double *events,
                                          size_t count, double now, size_t cap);
bool slopdesk_recovery_loss_window_observing(double window_seconds, size_t min_events,
                                             const double *events, size_t count, double now);

/* ---------------------------------------------------------------------------- *
 * The FEC ladder: measured loss becoming the per-frame redundancy both ends agree on.
 *
 * Not a handle, even though the tier decision looks stateful: the state IS the answer, so it
 * crosses by value — one SlopDeskFecTierState in, one out. Three scalars are cheaper to copy than a
 * handle is to own, and a value the host keeps in its own session struct cannot drift from a
 * counter living somewhere else.
 *
 * `group_size` answers false, writing nothing, for the OFF tier that carries no parity — the
 * absence is the return value and not a reserved size because EVERY size is legal here, including
 * the 0 a caller may pass as its own default. It is TOTAL over every uint8_t: a tier read off a
 * corrupt fragment must never trap, and a reserved value falls back to the caller's default.
 *
 * The two `resolve_*` calls take the RAW environment strings because the lookup is the app's —
 * Swift's EnvConfig reads the process environment and the settings overlay a GUI toggle writes —
 * while what the string MEANS (parse, default, clamp, the joint k + m <= 255 field bound) is the
 * codec's. A missing variable and an unparseable one answer the same, so absence needs no flag:
 * pass (NULL, 0). `resolve_group_size` takes both strings because the bound is joint.
 *
 * `constant(index)` vends the ladder's numbers so neither end writes one the other also writes:
 * 0 default tier · 1/2/3 the parity tiers CLEAN/NORMAL/BURST · 4 relax dwell reports · 5 the
 * sticky-relax window · 6 the multi-loss default k · 7/8 the m bounds · 9/10 the k bounds · 11
 * the multi-loss default m, which is NOT index 7: `M_MIN` answers "how low may a caller drive the
 * parity count", index 11 answers "what does a caller who has not chosen get". They are both 1
 * today, and that coincidence is exactly why the settings sheet had regrown its own literal.
 *
 * `multi_loss_active(m)` is the THRESHOLD rather than a bound — `m >= 2` is what changes the
 * parity count per group on the wire, selects the true [k + m, k] code over the XOR-equivalent
 * default, and is what `wire_tier`'s `multi_loss_active` argument is asking about. It is a door of
 * its own because the two bounds cannot stand in for it: `M_MIN` is 1, so a caller composing the
 * threshold out of `constant(7)`/`constant(8)` would answer "always active".
 * ---------------------------------------------------------------------------- */

typedef struct {
  uint32_t relax_streak;
  uint32_t sticky_relax_remaining;
  uint8_t tier;
} SlopDeskFecTierState;

uint32_t slopdesk_adaptive_fec_constant(uint8_t index);
bool slopdesk_adaptive_fec_group_size(uint8_t tier, size_t default_group_size, size_t *out);
uint8_t slopdesk_adaptive_fec_wire_tier(uint8_t adaptive_tier, bool adaptive_m_enabled,
                                        bool multi_loss_active);
uint8_t slopdesk_adaptive_fec_tier(double loss, uint8_t previous_tier, bool allow_off);
SlopDeskFecTierState slopdesk_adaptive_fec_next_tier_state(double loss, SlopDeskFecTierState state,
                                                           uint32_t dwell, bool allow_off,
                                                           bool saw_unrecovered_loss);
SlopDeskFecTierState slopdesk_adaptive_fec_next_parity_tier_state(double loss,
                                                                  SlopDeskFecTierState state,
                                                                  uint32_t dwell,
                                                                  bool saw_unrecovered_loss);
size_t slopdesk_adaptive_fec_resolve_parity_count(const uint8_t *raw, size_t len);
size_t slopdesk_adaptive_fec_resolve_group_size(const uint8_t *raw_k, size_t len_k,
                                                const uint8_t *raw_m, size_t len_m);
bool slopdesk_adaptive_fec_multi_loss_active(size_t parity_count);

/* ---------------------------------------------------------------------------- *
 * The video datagram codec: the 19-byte header, both directions.
 *
 * Not a handle — a datagram carries nothing forward, so the codec has no state to keep. Every
 * caller on either side reaches this one: the host's send path, the client's router (which reads
 * frameID and hostSendTsMillis off a datagram before it knows where the datagram goes) and the
 * golden generator.
 *
 * Decoding answers a header and an OFFSET, never a payload: the caller still holds the datagram it
 * just handed over, so copying the payload back would copy every byte of every frame a second time.
 * Slice your own buffer at `payload_offset` — the wire layout stays on this side, so no caller has
 * to spell 19.
 *
 * `decode` answers false — writing nothing — for a datagram too short to hold a header, or one
 * whose declared payload runs past its end, which is what a corrupt packet on an unauthenticated
 * socket looks like. A NULL `out` is inert: it still parses and still answers.
 *
 * `encode` takes no payload_length: the declared length comes from the payload, and the two cannot
 * disagree on the wire if only one of them exists. It returns bytes NEEDED, under §4's convention.
 * ---------------------------------------------------------------------------- */

typedef struct {
  uint32_t stream_seq;
  uint32_t frame_id;
  uint32_t host_send_ts_millis;
  uint16_t frag_index;
  uint16_t frag_count;
  uint16_t payload_length;
  uint8_t flags;
  uint8_t payload_offset;
} SlopDeskVideoFragmentHeader;

bool slopdesk_video_fragment_decode(const uint8_t *bytes, size_t len,
                                    SlopDeskVideoFragmentHeader *out);
size_t slopdesk_video_fragment_encode(uint32_t stream_seq, uint32_t frame_id, uint16_t frag_index,
                                      uint16_t frag_count, uint8_t flags,
                                      uint32_t host_send_ts_millis, const uint8_t *payload,
                                      size_t payload_len, uint8_t *out, size_t cap);
// A fragment size budget: 0 the header, 1 the whole datagram (the MTU claim), 2 the payload
// the two leave between them. Unknown index answers 0, which packetizes nothing.
size_t slopdesk_video_fragment_size(uint8_t index);

// Where the adaptive-FEC tier sits in the flags byte: 0 the shift, 1 the mask. Unknown index
// answers 0, which reads every frame as tier 0 — the plain wire.
uint8_t slopdesk_video_flags_tier_layout(uint8_t index);

/* ---------------------------------------------------------------------------- *
 * The three measurements the capture path takes on a frame it has just locked.
 *
 * These are the ONE family of entries that does not take bytes the caller owns. The pixels only
 * exist as an address inside a Core Video mapping, so a plane crosses as a base address and a row
 * stride, and the lock around the call is what `withUnsafeBytes` is everywhere else. The length is
 * `stride * rows`, computed with a checked multiply on the Rust side: an absurd stride is a defined
 * "no measurement", never a read past the mapping.
 *
 * hash_nv12 answers one 64-bit value per frame, over the VISIBLE bytes of each row only, so the
 * same picture hashes equal however the capture padded it. A null luma plane, a degenerate
 * dimension, a stride narrower than the width or an overflowing product answer the SENTINEL, which
 * slopdesk_video_frame_hash_sentinel vends rather than either side spelling it.
 *
 * scroll_nv12 and adaptive_qp_nv12 both compare two planes of the same picture, so they take the
 * pair as one value: two planes that may be padded differently, and the one width and height they
 * are both read at. An unmeasurable pair is a defined answer for each — a no-shift estimate whose
 * band is -1/-1, and the configured static ceiling with a zero change — and never a fault.
 *
 * The results come back BY VALUE rather than through an out pointer: each is four words or fewer,
 * so there is no buffer to size, nothing to write into and no §4 sizing call.
 * ---------------------------------------------------------------------------- */

typedef struct {
  const uint8_t *base;
  size_t stride;
} SlopDeskLumaPlane;

typedef struct {
  SlopDeskLumaPlane prev;
  SlopDeskLumaPlane cur;
  size_t width;
  size_t height;
} SlopDeskLumaPair;

typedef struct {
  int32_t shift;
  uint32_t confidence_milli;
  int32_t band_top;
  int32_t band_bottom;
} SlopDeskScrollEstimate;

typedef struct {
  uint8_t qp;
  uint32_t change_milli;
} SlopDeskQpDecision;

uint64_t slopdesk_video_frame_hash_sentinel(void);
uint64_t slopdesk_video_frame_hash_nv12(const uint8_t *y, size_t y_stride, size_t width,
                                        size_t height, const uint8_t *cbcr, size_t cbcr_stride);
SlopDeskScrollEstimate slopdesk_video_scroll_nv12(SlopDeskLumaPair pair, size_t max_shift,
                                                  uint8_t quantize_shift);
SlopDeskQpDecision slopdesk_video_adaptive_qp_nv12(SlopDeskLumaPair pair, uint8_t qp_sharp,
                                                   uint8_t qp_max, uint32_t b_lo_milli,
                                                   uint32_t b_hi_milli);

/* ---------------------------------------------------------------------------- *
 * Four pure policies with no state behind them: a colour matrix, a click, a buffer, a verdict.
 *
 * Like the frame measurements above, these answer BY VALUE — every argument and every result is a
 * scalar or a handful of them, so nothing here takes bytes the caller owns and there is no §4
 * sizing call.
 *
 * ycbcr_coefficients and coord_window_point are the two the golden corpus pins as raw IEEE bit
 * patterns, which is why they cross at all: a second implementation of either agrees with the first
 * until a compiler fuses a multiply and an add, and then a click lands a pixel off on one machine.
 * The multiply and the add stay separate on the Rust side, and every coefficient stays 32-bit end
 * to end — an f64 intermediate narrowed on the way out moves the low bits the corpus pins.
 *
 * playout_step_ms takes the caller's knobs already resolved from the environment and clamps each
 * into its band on the Rust side, so an absent or hostile knob cannot widen the buffer past its
 * ceiling. Jitter is in SECONDS; everything else is milliseconds, in and out.
 *
 * stall_verdict's two arrival stamps carry their own presence flag rather than a sentinel time,
 * because "no frame has EVER arrived" and "the last frame arrived at time zero" are different
 * states and only one of them can be a stall. Under idle_skip_active the host is suppressing frames
 * BY DESIGN, so only the heartbeat counts; otherwise the newer of the two does.
 * ---------------------------------------------------------------------------- */

typedef struct {
  float luma_scale;
  float luma_bias;
  float chroma_bias;
  float cr_to_r;
  float cb_to_g;
  float cr_to_g;
  float cb_to_b;
} SlopDeskYCbCrCoefficients;

typedef struct {
  double x;
  double y;
} SlopDeskVideoPoint;

typedef struct {
  double now;
  double last_frame_at;
  double last_heartbeat_at;
  double threshold;
  bool   has_frame;
  bool   has_heartbeat;
  bool   connected;
  bool   idle_skip_active;
} SlopDeskLiveness;

#define SLOPDESK_STREAM_LIVE 0u
#define SLOPDESK_STREAM_STALLED 1u
#define SLOPDESK_STREAM_NOT_CONNECTED 2u
#define SLOPDESK_STREAM_UNKNOWN 3u

SlopDeskYCbCrCoefficients slopdesk_ycbcr_coefficients(bool full_range);
SlopDeskVideoPoint slopdesk_coord_window_point(double normalized_x, double normalized_y,
                                               double bounds_x, double bounds_y,
                                               double bounds_width, double bounds_height);
double slopdesk_playout_step_ms(double jitter_seconds, double prev_playout_ms,
                                double shrink_step_ms, double k, double base_ms, double floor_ms,
                                double ceil_ms);
/* The playout law's own default for each knob, in the units the knobs are configured in: 0 the
 * dimensionless k, 1 base, 2 floor, 3 ceiling, 4 shrink step (the last four in ms). An unknown
 * index answers NaN, which the law already reads as "take the default". */
double slopdesk_playout_default_ms(unsigned char index);
uint32_t slopdesk_stream_stall_verdict(SlopDeskLiveness inputs);

/* The aspect geometry, and the virtual-display re-create throttle. The first two are pinned
 * bit-exactly: `view_point` is the exact inverse of the input encoder's normalise, so the cursor
 * overlay lands where the click does, and a contracted multiply-add on one side would move it. */

typedef struct {
  double width;
  double height;
} SlopDeskVideoSize;

typedef struct {
  double x;
  double y;
  double width;
  double height;
} SlopDeskVideoRect;

#define SLOPDESK_CONTENT_MODE_FIT 0u
#define SLOPDESK_CONTENT_MODE_FILL 1u

double slopdesk_geometry_intersection_area(SlopDeskVideoRect first, SlopDeskVideoRect second);
SlopDeskVideoRect slopdesk_geometry_displayed_video_rect(SlopDeskVideoSize view,
                                                         SlopDeskVideoSize video_native,
                                                         uint32_t mode);
SlopDeskVideoPoint slopdesk_geometry_view_point(SlopDeskVideoPoint host_point,
                                                SlopDeskVideoSize view,
                                                SlopDeskVideoSize video_native, double zoom,
                                                SlopDeskVideoPoint pan, uint32_t mode);

/* ---- The window record, and the two things decided over a list of them --------------------------
 *
 * The record is declared HERE, outside the macOS-only region, although only a macOS door ever fills
 * one: `slopdesk_cgwindow_in_front_of` answers an array of these and the `slopdesk_capture_*` doors
 * below consume it unchanged. Declaring the layout on both sides of the `TARGET_OS_OSX` guard is how
 * a field reorder ships as green tests and a scrambled capture region.
 *
 * The DECIDERS are portable because they decide rather than read: `golden/golden_vectors.json` pins
 * the union and the hysteresis gate as raw `f64` bit patterns, and that check runs wherever the
 * crate builds. */

typedef struct {
  SlopDeskVideoRect bounds; // CG global points, top-left origin
  uint32_t window_id;       // per-boot and reusable — names a window only with owner_pid
  int32_t owner_pid;        // the owning process
  int32_t layer;            // 0 an ordinary window, 101 a pop-up menu, 24 the menu bar
} SlopDeskWindowRecord;

// The display a window sits on: the one holding its CENTRE, else the LARGEST. false — there are no
// displays at all — leaves *out untouched, and the caller then reports the window's own size as its
// resize ceiling rather than a zero one nobody could resize to.
bool slopdesk_window_display_for_frame(SlopDeskVideoRect frame, const SlopDeskVideoRect *displays,
                                       size_t count, SlopDeskVideoRect *out);

// DIALOG-EXPAND. `windows` is the front-to-back slice strictly IN FRONT of the target — exactly what
// slopdesk_cgwindow_in_front_of answers — and the region is the target frame ∪ every same-pid panel
// on an associatable layer that overlaps it enough, clamped to the display.
//
// The overlap fraction and the hysteresis delta do NOT cross: they are the crate's constants, and
// the one caller took both defaults, so carrying them over would have made a second place to change
// one.
SlopDeskVideoRect slopdesk_capture_union_region(SlopDeskVideoRect target, uint32_t target_window_id,
                                                int32_t target_pid,
                                                const SlopDeskWindowRecord *windows, size_t count,
                                                SlopDeskVideoRect display);

// The OPAQUE pieces inside that region — the target, then each panel — so the client can mask the
// black flank BETWEEN them, which the bounding box cannot express. The answer is the count NEEDED.
size_t slopdesk_capture_content_rects(SlopDeskVideoRect target, uint32_t target_window_id,
                                      int32_t target_pid, const SlopDeskWindowRecord *windows,
                                      size_t count, SlopDeskVideoRect display,
                                      SlopDeskVideoRect *out, size_t cap);

// Whether a region change is worth acting on — every one is an encoder rebuild and an IDR.
bool slopdesk_capture_should_retarget(SlopDeskVideoRect current, SlopDeskVideoRect desired);

// Whether a window MOVE should re-origin the input and cursor mapping to the plain window frame.
// The pair is this ABI's spelling of `CGRect?`: active_region is read only when region_active.
bool slopdesk_capture_should_reorigin(SlopDeskVideoRect active_region, bool region_active);

#define SLOPDESK_REGION_HOLD 0u
#define SLOPDESK_REGION_EXPAND 1u
#define SLOPDESK_REGION_CONTRACT 2u

// What a freshly measured union means for a capture currently at `current` — has_current false
// being the plain window frame. Answers one of the three SLOPDESK_REGION_* verdicts, and writes
// *out only for EXPAND. A null out cannot carry an expansion, so it is answered HOLD.
uint32_t slopdesk_capture_region_decision(SlopDeskVideoRect union_global,
                                          SlopDeskVideoRect window_frame, SlopDeskVideoRect current,
                                          bool has_current, SlopDeskVideoRect *out);

/* The cursor OVERLAY placement — bit-exact with `view_point` above, because the overlay must track
 * the same displayed pixel a click lands on at every zoom and in every letterbox. */
SlopDeskVideoRect slopdesk_cursor_layer_frame_scalar(SlopDeskVideoPoint position,
                                                     SlopDeskVideoPoint hotspot, double video_scale,
                                                     SlopDeskVideoSize cursor_size);
SlopDeskVideoRect slopdesk_cursor_layer_frame_fit(SlopDeskVideoPoint position,
                                                  SlopDeskVideoPoint hotspot,
                                                  SlopDeskVideoSize view,
                                                  SlopDeskVideoSize video_native, double zoom,
                                                  SlopDeskVideoPoint pan,
                                                  SlopDeskVideoSize cursor_size, uint32_t mode);
double slopdesk_cursor_bottom_left_origin_y(double top_left_y, double height, double parent_height);
bool slopdesk_cursor_is_placeable(SlopDeskVideoRect frame);
SlopDeskVideoSize slopdesk_cursor_rendered_shape_size(SlopDeskVideoSize logical,
                                                      SlopDeskVideoSize bitmap_pixels);

/* The `windowList` reply's arrangement: on-screen first, untitled off-screen entries dropped. The
 * windows never cross — the two flags do, and the answer is the caller's own indices. */
size_t slopdesk_arrange_streamable_windows(const bool *on_screen, const bool *titled, size_t count,
                                           uint32_t *order, size_t cap);

double slopdesk_vd_recreate_cooldown(void);
bool slopdesk_vd_recreate_should_attempt(double now, double last_attempt, bool has_last_attempt,
                                         double cooldown, bool attempt_in_flight);
size_t slopdesk_vd_channels_to_disconnect(const uint32_t *parked, size_t parked_count,
                                          const uint32_t *live, size_t live_count, uint32_t *out,
                                          size_t cap);

/* The keepalive timing contract, and the stall threshold it is sized against. ONE record, because
 * the five numbers are one argument: the stall threshold tolerates two lost host heartbeats, and
 * the reaper tick is what makes the worst-case reclaim `idle_timeout + reaper_tick`. */
typedef struct {
  double keepalive_interval;
  double idle_timeout;
  double reaper_tick;
  double host_heartbeat_interval;
  double stall_threshold;
} SlopDeskKeepaliveTiming;

SlopDeskKeepaliveTiming slopdesk_keepalive_timing(void);

/* ---------------------------------------------------------------------------- *
 * The host's four smallest send-path decisions: suppress, re-sharpen, budget, degrade.
 *
 * All by value — the far side reads every field of every one of them, and none holds anything
 * between calls. The stillness decider is a FOLD: hand back the two numbers you were last given.
 * ---------------------------------------------------------------------------- */

typedef struct {
  bool is_first_frame;
  bool forced_keyframe_pending;
  bool recovery_pending;
  bool heartbeat_due;
  bool ltr_refresh_due;
  bool self_heal_due;
} SlopDeskFrameObligations;

typedef struct {
  size_t consecutive_equal;
  bool   fired_this_rest;
} SlopDeskStillnessCrisp;

typedef struct {
  double  default_bits_per_pixel;
  int64_t minimum_bitrate;
} SlopDeskLiveBitrateDefaults;

#define SLOPDESK_CAPTURE_ABANDON 0u
#define SLOPDESK_CAPTURE_REBUILD_PLAIN_WINDOW 1u
#define SLOPDESK_CAPTURE_DISCONNECT 2u

bool slopdesk_should_suppress_static_frame(bool hash_equal_to_last,
                                           SlopDeskFrameObligations obligations);

SlopDeskStillnessCrisp slopdesk_stillness_crisp_new(void);
SlopDeskStillnessCrisp slopdesk_stillness_crisp_on_frame(SlopDeskStillnessCrisp state,
                                                         bool hash_equal_to_previous);
bool slopdesk_stillness_crisp_should_fire(SlopDeskStillnessCrisp state, size_t rest_threshold);
SlopDeskStillnessCrisp slopdesk_stillness_crisp_note_fired(SlopDeskStillnessCrisp state);

SlopDeskLiveBitrateDefaults slopdesk_live_bitrate_defaults(void);
double slopdesk_live_bitrate_bits_per_pixel(const uint8_t *raw, size_t raw_len);
int64_t slopdesk_live_bitrate_target(int64_t pixel_width, int64_t pixel_height, int64_t fps,
                                     int64_t floor, double bits_per_pixel_per_frame);

uint32_t slopdesk_capture_failure_action(bool media_flowing, bool superseded,
                                         bool is_fallback_rebuild);

/* ---------------------------------------------------------------------------- *
 * The host's four bounded accumulators: the LTR map, the dedup window, the idle reaper, the
 * retransmit ring.
 *
 * All four are HANDLES, and for the same reason: each holds something across many calls that the
 * near side almost never reads. The ring is the sharp case — it is MEGABYTES of sent datagrams and
 * a repair is the handful a client actually lost, so a selection reports the shape and one take
 * copies it out.
 * ---------------------------------------------------------------------------- */

typedef struct SlopDeskLtrController SlopDeskLtrController;
typedef struct SlopDeskRecoveryDeduper SlopDeskRecoveryDeduper;
typedef struct SlopDeskIdleReaper SlopDeskIdleReaper;
typedef struct SlopDeskRetransmitRing SlopDeskRetransmitRing;

#define SLOPDESK_LTR_REQUEST_REFRESH 0u
#define SLOPDESK_LTR_REQUEST_IDR 1u
#define SLOPDESK_LTR_ACTION_REFRESH 0u
#define SLOPDESK_LTR_ACTION_IDR 1u

typedef struct {
  size_t frame_token_cap;
  size_t acknowledged_token_cap;
} SlopDeskLtrCaps;

typedef struct {
  double last_inbound;
  bool   saw_keepalive;
} SlopDeskFlowRecord;

typedef struct {
  double window_seconds;
  size_t capacity;
} SlopDeskRecoveryDedupeDefaults;

typedef struct {
  uint32_t offset;
  uint32_t length;
} SlopDeskByteSpan;

/* ---------------------------------------------------------------------------- *
 * cli — what the `slopdesk` CLI asks: its flags, its completion scripts, its
 * config file and its tables.
 *
 * Everything crosses BY VALUE, because a CLI has no accumulator: a parse is a
 * function of its argv, a script is a function of its shell, a table is a
 * function of its rows. Nothing here outlives a call, so there is no handle.
 *
 * The rows cross as JSON TEXT rather than as records. They arrive at the near
 * side as JSON — the control socket answers NDJSON — and leave as JSON or as a
 * table, so decoding them into a flat record on the way through would mean a
 * schema for six lists and a re-encode on both sides.
 *
 * `config validate` asks the caller back: the grammar it checks against is the
 * app's keybind parser, which this side has no business depending on, so it
 * crosses as a callback with its context.
 * ---------------------------------------------------------------------------- */

#define SLOPDESK_CLI_TEXT 0u
#define SLOPDESK_CLI_JSON 1u

#define SLOPDESK_CLI_OK 0u
#define SLOPDESK_CLI_UNKNOWN_FLAG 1u
#define SLOPDESK_CLI_MISSING_VALUE 2u
#define SLOPDESK_CLI_INVALID_VALUE 3u

#define SLOPDESK_SHELL_BASH 0u
#define SLOPDESK_SHELL_ZSH 1u
#define SLOPDESK_SHELL_FISH 2u
#define SLOPDESK_SHELL_ELVISH 3u
#define SLOPDESK_SHELL_POWERSHELL 4u

#define SLOPDESK_CLI_TABLE_WINDOWS 0u
#define SLOPDESK_CLI_TABLE_TABS 1u
#define SLOPDESK_CLI_TABLE_PANES 2u
#define SLOPDESK_CLI_TABLE_FONTS 3u
#define SLOPDESK_CLI_TABLE_KEYBINDS 4u
#define SLOPDESK_CLI_TABLE_CONFIG 5u

// How much a variable-length answer needs: how many records, and how many bytes
// of text.
typedef struct {
  size_t count;
  size_t arena_len;
} SlopDeskCliShape;

// One fully-parsed invocation. The token spans live in the caller's span array:
// the first rest_count are the residual arguments, the exec_count after them are
// the `-e` command.
typedef struct {
  SlopDeskByteSpan subcommand;
  SlopDeskByteSpan socket_path;
  SlopDeskByteSpan config_file;
  SlopDeskByteSpan error_flag;
  SlopDeskByteSpan error_value;
  int64_t timeout_ms;
  size_t rest_count;
  size_t exec_count;
  uint32_t format;
  uint32_t error;
  bool has_socket;
  bool has_config;
  bool has_exec;
  bool no_headers;
  bool assume_yes;
  bool wants_help;
  bool launch_gui;
} SlopDeskCliInvocation;

// One config-file syntax problem.
typedef struct {
  SlopDeskByteSpan message;
  size_t line;
} SlopDeskCliConfigError;

/* The grammar for one `keybind` line of the user's config. A parsed binding is a fixed record plus
 * three runs of variable-length bytes — the base key, the payload (a literal action's resolved
 * bytes, or a named action's id) and the argument — so it crosses as a record whose runs are
 * (offset, length) pairs into ONE arena the caller lends. Ask twice: once with a null arena to
 * learn `arena_len`, then again with that much room. A record whose runs did not fit comes back
 * `valid == false` — acting on a half-written payload would put bytes on a pane the user never
 * wrote. `has_arg` is a FLAG, not an empty run: the grammar refuses `goto_tab:`, so "no argument"
 * and "an empty one" are different answers and only one can arise. */

#define SLOPDESK_KEYBIND_TEXT   0u  /* text:<s> — the payload run is the literal bytes */
#define SLOPDESK_KEYBIND_CSI    1u  /* csi:<p>  — the payload run leads with ESC [ */
#define SLOPDESK_KEYBIND_ESC    2u  /* esc:<p>  — the payload run leads with ESC */
#define SLOPDESK_KEYBIND_NAMED  3u  /* a registry action; the payload run is its id */
#define SLOPDESK_KEYBIND_UNBIND 4u  /* unbind:<chord> — neither run carries anything */

typedef struct {
  uint32_t offset;
  uint32_t length;
} SlopDeskKeybindRun;

typedef struct {
  SlopDeskKeybindRun key;      /* the chord's base key, lowercased */
  SlopDeskKeybindRun payload;  /* the action's bytes, or a named action's id */
  SlopDeskKeybindRun arg;      /* meaningful only when `has_arg` */
  uint32_t kind;               /* one of SLOPDESK_KEYBIND_* */
  size_t   arena_len;          /* what the three runs need in total */
  bool     has_arg;
  bool     command;
  bool     shift;
  bool     option;
  bool     control;
  bool     valid;              /* false is the grammar's "drop this line" */
} SlopDeskKeybind;

SlopDeskKeybind slopdesk_keybind_parse_line(const uint8_t *line, size_t line_len,
                                            uint8_t *arena, size_t arena_cap);
bool slopdesk_keybind_is_valid(const uint8_t *line, size_t line_len);

/* ---- A config action NAME, as the binding id it rebinds ------------------------------------
 * The other half of a `keybind` line. `slopdesk_keybind_parse_line` above answers what the line
 * LOOKS like — a chord plus a named action; this answers which binding that action actually fires,
 * which is `slopdesk-workspace`'s registry rather than the grammar's. `0` is the refusal (an
 * unknown name, a `goto_tab` outside the nine per-digit bindings, or one of the three
 * libghostty-only responder actions that have no workspace action at all) and cannot collide with
 * an answer, because every id this vocabulary can name is a non-empty string. A zero-length or
 * NULL argument reads as NO argument: only `goto_tab` reads one, and `goto_tab:` is refused by the
 * grammar before it could ever reach here.                                                    */
size_t slopdesk_ws_binding_id_for_config_name(const uint8_t *name, size_t name_len,
                                              const uint8_t *arg, size_t arg_len,
                                              uint8_t *out, size_t cap);

/* The one spelling a base key is stored under, and the one text a chord is written with — the same
 * table that decides which spellings the grammar accepts. */
size_t slopdesk_keybind_canonical_key(const uint8_t *key, size_t key_len, uint8_t *out, size_t cap);
size_t slopdesk_keybind_canonical_chord(const uint8_t *key, size_t key_len, bool command, bool shift,
                                        bool option, bool control, uint8_t *out, size_t cap);
/* The same chord written for a HUMAN: the modifier glyphs in the platform's own order (⌃⌥⇧⌘) then
 * the key — a named key's printed symbol, or the key itself upper-cased, because a chord is stored
 * lower-cased with the shift in the modifiers and a menu prints ⌘D. */
size_t slopdesk_keybind_glyph(const uint8_t *key, size_t key_len, bool command, bool shift,
                              bool option, bool control, uint8_t *out, size_t cap);

/* The libghostty config text one set of terminal preferences spells. Two dozen strings and a dozen
 * switches, so rather than two dozen (ptr, len) pairs they cross as ONE record of named
 * (offset, length) runs into a single blob the caller interns — the keybind shape above, widened.
 * The two LISTS, the user's keybind lines and the theme's sixteen palette entries, cross as arrays
 * of runs rather than one delimited blob, because a delimiter is a thing a value could contain and
 * a count is not. Enum-valued preferences cross as the raw value the near side PERSISTS
 * (`primary-only`, `macos-like`, `block_hollow`); which libghostty key that actuates is decided on
 * the far side, and a raw value this build does not know takes the branch that emits nothing.
 * Ask twice: a null `out` reports the length, then lend that much. */

typedef struct {
  uint32_t offset;
  uint32_t length;
} SlopDeskConfigRun;

typedef struct {
  SlopDeskConfigRun family;             /* empty skips the chain, fallbacks included */
  SlopDeskConfigRun fallback;           /* comma-separated, each a repeated font-family line */
  SlopDeskConfigRun weight;
  SlopDeskConfigRun family_bold;        /* honoured only when auto_match_weight_style is off */
  SlopDeskConfigRun family_italic;
  SlopDeskConfigRun family_bold_italic;
  SlopDeskConfigRun ligatures;          /* off / calt / dlig */
  SlopDeskConfigRun bold;               /* auto / off / primary-only / synthetic */
  SlopDeskConfigRun italic;
  SlopDeskConfigRun blending;           /* default / macos-like */
  double size;
  double cell_height_percent;           /* meaningful only when has_cell_height */
  bool   auto_match_weight_style;
  bool   ligatures_alphabet;
  bool   has_cell_height;               /* a FLAG: 0% is a real answer, it is what "tight" asks */
} SlopDeskTerminalFont;

typedef struct {
  SlopDeskConfigRun theme;
  SlopDeskConfigRun background;
  SlopDeskConfigRun foreground;
  SlopDeskConfigRun background_override;  /* replaces the pref colour when non-empty */
  SlopDeskConfigRun foreground_override;
  SlopDeskConfigRun selection_background;
} SlopDeskTerminalColors;

typedef struct {
  SlopDeskConfigRun style;   /* block / block_hollow / bar / underline */
  SlopDeskConfigRun blink;   /* on / off; anything else defers to DEC mode 12 with no line */
  SlopDeskConfigRun color;
  SlopDeskConfigRun text_color;
  double opacity;
} SlopDeskTerminalCursor;

typedef struct {
  SlopDeskConfigRun clipboard_read;      /* allow / deny / ask */
  SlopDeskConfigRun clipboard_write;
  SlopDeskConfigRun mouse_shift_capture; /* false / true / always / never */
  SlopDeskConfigRun right_click_action;
  SlopDeskConfigRun macos_option_as_alt; /* false / true / left / right */
  double scroll_multiplier;              /* drives both axes, keeping libghostty's 1:3 ratio */
  bool copy_on_select;
  bool trim_trailing;
  bool clear_on_typing;
  bool clear_on_copy;
  bool paste_protection;
  bool bracketed_safe;
  bool hide_mouse_while_typing;
  bool click_to_move;
  bool allow_mouse_capture;
  bool shift_arrow_select;               /* off UNBINDS; the fork binds these by default */
} SlopDeskTerminalControls;

typedef struct {
  SlopDeskTerminalFont     font;
  SlopDeskTerminalColors   colors;
  SlopDeskTerminalCursor   cursor;
  SlopDeskTerminalControls controls;     /* meaningful only when has_controls */
  int64_t scrollback_lines;
  bool    has_controls;                  /* absent ≠ every switch off: absent emits no line */
} SlopDeskTerminalConfig;

