SlopDeskPacerDepth slopdesk_pacer_depth_note_arrival(SlopDeskPacerDepth policy, double now);
SlopDeskPacerDepthPresent slopdesk_pacer_depth_note_present(SlopDeskPacerDepth policy, double now);
